window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Tryb przypuszczający (Konjunktiv II) i zdania z wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Na twoim miejscu …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Rzeczywistość Evy – życzenia Evy. Uzupełnij: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Ale chciałaby być wyższa.","why":"*grösser sein*: forma życzenia od *sein* to **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Ale chciałaby dobrze mówić po hiszpańsku.","why":"Na końcu stoi bezokolicznik (*sprechen*), więc życzenie to **würde** + bezokolicznik.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Ale wolałaby pracować jako przewodniczka wycieczek.","why":"Bezokolicznik na końcu (*arbeiten*) → **würde** + bezokolicznik. *lieber* = raczej, chętniej.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Ale chciałaby mieć duże mieszkanie.","why":"*eine Wohnung haben*: forma życzenia od *haben* to **hätte**. Bezokolicznik nie jest potrzebny.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Co myślą ci ludzie?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każdy obrazek do wyrażenia z ramki.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Gdybym nie musiał pracować, siedziałbym teraz w ogrodzie.","why":"Obrazek 1 pokazuje go przy pracy, a potem jak marzy na leżaku. Po zdaniu z *wenn* zdanie główne zaczyna się od czasownika (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Gdybym miał samochód, nie musiałbym jeździć na rowerze w deszczu.","why":"Jedzie na rowerze w deszczu; samochód by mu tego oszczędził. *müsste* to Konjunktiv II od *müssen*. *Velo* to szwajcarskie słowo na *Fahrrad* (rower).","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Gdyby autobus nie miał opóźnienia, byłabym punktualnie w biurze.","why":"Przez spóźniony autobus ona spóźnia się do pracy. *wäre* to Konjunktiv II od *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a: zacznij od zdania głównego, potem zdanie z wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Nie musiałbym jeździć na rowerze w deszczu, gdybym miał samochód.","why":"Najpierw zdanie główne, potem zdanie z *wenn*. W zdaniu z *wenn* czasownik (*hätte*) idzie na koniec.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Byłabym punktualnie w biurze, gdyby autobus nie miał opóźnienia.","why":"Ten sam wzór: zdanie główne, przecinek, *wenn* … czasownik na końcu (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowami z ramki. Każde słowo jest użyte raz; przekreślone są użyte w przykładzie.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Zrobiłabym niektóre rzeczy inaczej, gdybym była szefową w naszej firmie.","why":"*machen* na końcu → **würde** + bezokolicznik. *Chefin sein* → **wäre**, na końcu zdania z *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Gdybym był Markiem, koniecznie zacząłbym naukę zawodu.","why":"*Marco sein* → **wäre** (jak w *Wenn ich du wäre …*). Zdanie główne ma bezokolicznik *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Gdybym mogła swobodnie decydować, pracowałabym w małej firmie.","why":"*frei entscheiden können* → **könnte** na końcu zdania z *wenn*. Zdanie główne z *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Gdybyśmy mieli dzieci, musiałabym pracować tylko na pół etatu.","why":"*Kinder haben* z *wir* → **hätten**. Ramka zostawia **müsste** na ostatnią lukę.","source":"k2","check":"W b, c i e zarówno *müsste*, jak i *würde* są poprawne po niemiecku (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* jest równie dobre). Ramka mówi tylko, które trzy luki dostają *würde*, a która *müsste*; ten klucz to najbardziej prawdopodobny podział. Zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Muszę się spieszyć z powodu pracy.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Przepisz odpowiedzi, używając spójnika weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Bo moja dziewczyna jest niepunktualna.","why":"*wegen* + rzeczownik zamienia się w *weil* + zdanie z czasownikiem; czasownik (*ist*) idzie na koniec.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Bo pogoda jest zła.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; po *weil* czasownik idzie na koniec.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Bo mam ważne spotkanie.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (biernik po *haben*); czasownik na końcu.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Uzupełnij: wegen – weshalb – weil – deswegen – denn. Jednego słowa można użyć więcej niż raz.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Słabo go rozumiem z powodu jego wymowy.","why":"Dalej stoi rzeczownik (*seiner Aussprache*, dopełniacz), a nie zdanie → przyimek **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Kiedyś chciałbym pojechać do Włoch, bo chciałbym zobaczyć morze.","why":"Po luce czasownik zostaje na drugim miejscu (*ich möchte*) → **denn**. Z *weil* poszedłby na koniec.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Muszę poprawić rozumienie ze słuchu, dlatego oglądam dużo filmów.","why":"Druga część to skutek, a czasownik stoi zaraz po luce (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Moje dzieci szybko nauczyły się niemieckiego, bo w przedszkolu zawsze są razem ze szwajcarskimi dziećmi.","why":"Czasownik jest na końcu (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Dlaczego zapisujesz słowa na karteczkach?","why":"Potrzebny jest zaimek pytający: **Weshalb** znaczy *warum* (dlaczego)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Moja siostra mówi już prawie płynnie po niemiecku, dlatego może mi pomagać w nauce niemieckiego.","why":"Skutek, a czasownik stoi zaraz po luce (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Na kursie językowym. Uzupełnij: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Nie mogłem zrobić ostatniego ćwiczenia, bo go nie zrozumiałem.","why":"Czasownik jest na końcu (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"W rejestracji nikogo nie było. Dlatego wróciłem do domu.","why":"Nowe zdanie, które podaje skutek, z czasownikiem zaraz po luce (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Ze względu na dobre oceny nie musiałem pisać testu na początku kursu.","why":"Dalej stoi grupa rzeczownikowa (*meiner guten Noten*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Jest dodatkowy kurs językowy, bo zapisało się bardzo wielu uczestników.","why":"Czasownik jest na końcu (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Wczoraj niestety nie mogłem przyjść na kurs z powodu bólu zębów.","why":"Dalej stoi grupa rzeczownikowa (*meiner Zahnschmerzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Kto znajdzie najlepsze wymówki? Wybierz jedną sytuację i napisz. Przykładowe odpowiedzi to tylko jedna z możliwości.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Niestety nie mogłem posprzątać kuchni, bo nagle bardzo rozbolały mnie plecy. Musiałem się położyć. Dlatego obejrzałem film.","why":"Używa *weil* (czasownik na końcu: *hatte*) i *Deswegen* (czasownik zaraz po nim: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Z powodu grypy nie poszedłem na egzamin końcowy. Miałem wysoką gorączkę, dlatego zostałem w łóżku.","why":"Używa *wegen* + dopełniacz (*einer Grippe*) i *deswegen* + czasownik (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Bardzo mi przykro! Niestety się spóźniłem, bo na autostradzie był wypadek. Przez korek straciłem dwie godziny.","why":"*denn* zostawia czasownik na drugim miejscu (*war*). *wegen des Staus*: dopełniacz od *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Dorastanie z kilkoma językami · czytanie, wpis na forum, krzyżówka, ulubione słowa","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Dwa lub trzy języki w jednej rodzinie – żaden problem?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i przy każdym zdaniu napisz imię osoby, która je mówi.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"„Dzieci chcą mówić tym samym językiem co ich przyjaciele.” – Janusz","why":"Janusz (tekst B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"„Przecież to dobrze, kiedy ktoś bardzo dobrze mówi w kilku językach.” – Yara","why":"Yara (tekst C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"„Moje dzieci przeskakują między dwoma językami.” – Amira","why":"Amira (tekst A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Tylko ona mówi o swoich własnych dzieciach."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Co jest prawdą? Przeczytaj teksty jeszcze raz. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Dzieci Amiry mówią lepiej po arabsku niż po niemiecku. → prawda","why":"Rodzina zawsze mówi w domu po arabsku: *Darum können das die Kinder viel besser.* (Ich niemiecki to tutaj szwajcarski niemiecki.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"W rodzinie Amiry mówi się tylko po niemiecku. → fałsz","why":"Odwrotnie: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz uczył się niemieckiego przez sześć lat. → fałsz","why":"Miał sześć lat, kiedy rodzina się przeprowadziła (*als ich sechs Jahre alt war*), a po roku mówił płynnie standardowym niemieckim (Hochdeutsch)."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz i jego siostra nie chcieli mówić z rodzicami po polsku. → prawda","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara mówi płynnie w trzech językach. → prawda","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Niemiecki to jej czwarty język i jeszcze nie mówi nim dobrze."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara wkrótce zacznie też uczyć się niemieckiego. → fałsz","why":"Nie zaczyna wkrótce (*bald*): uczy się niemieckiego już od dwóch lat (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Napisz wpis na forum. Po debacie telewizyjnej o dorastaniu z kilkoma językami znajdujesz na forum internetowym programu taką opinię:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Zrób notatki do czterech pytań. Wystarczą krótkie notatki, bez pełnych zdań. Przykładowe notatki to jedna z możliwości.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Tak: syn mojej sąsiadki – włoski z mamą, szwajcarski niemiecki w szkole","why":"Tylko notatki: imię lub osoba i jakie języki gdzie."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"nauka dwóch języków bez kursu, kontakt z rodziną za granicą, korzyści w pracy","why":"Zbierz dwie lub trzy zalety; będą ci potrzebne do *Ich finde es sehr gut, dass …* w b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mieszanie języków, jeden język jest słabszy, dużo pracy dla rodziców","why":"To trafi do *Es könnte schwierig sein, dass …* i *Auf der anderen Seite …* w b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"nie – dzieci dobrze uczą się dwóch języków, jeśli rodzice dużo z nimi rozmawiają","why":"Zdecyduj, czy tak, czy nie, i podaj jeden powód – z tego powstanie *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Teraz napisz swoją opinię na ten temat (około 80 słów). Wykorzystaj swoje notatki z punktu a i kilka podanych zwrotów.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Nie zgadzam się z Sandrą, bo wiele dzieci uczy się dwóch języków bez problemów. Syn mojej sąsiadki dorasta z włoskim i niemieckim. Z mamą mówi po włosku, a w szkole szwajcarskim niemieckim. Uważam, że to bardzo dobrze, że tak wcześnie uczy się dwóch języków. Trudne mogłoby być to, że czasem miesza języki. Z drugiej strony u małych dzieci to normalne. Najważniejsze ze wszystkiego jest to, żeby rodzice dużo rozmawiali z dzieckiem. Dlatego każde z rodziców powinno mówić swoim własnym językiem.","why":"Około 85 słów, z sześcioma zwrotami. *denn* zostawia czasownik na drugim miejscu (*lernen*); po *Deswegen* czasownik stoi zaraz potem (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Rozwiąż krzyżówkę. Każde zdanie podaje pierwszą literę brakującego słowa. Siatki tu nie ma: wpisz całe słowo. W siatce w książce Ä zajmuje jedną kratkę.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Naszą ojczyzną jest Hiszpania. Pochodzimy z Hiszpanii.","why":"*aus einem Land stammen* = pochodzić z jakiegoś kraju (jak *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda i Mike nie widzą się przez sześć miesięcy. To długa rozłąka.","why":"*die Trennung* = rozłąka, rozstanie, rzeczownik od *sich trennen*. *eine lange* → rzeczownik rodzaju żeńskiego."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Niemiecki i arabski nie mają tego samego pisma.","why":"*die Schrift* = pismo, czyli litery, którymi zapisuje się język. Arabski używa innego alfabetu."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter mieszka teraz w Ameryce. Odkąd tam mieszka, bardzo się zmienił.","why":"*sich verändern* = zmieniać się (o człowieku). Perfekt: *hat sich verändert*. Ä zajmuje jedną kratkę."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Ona pisze książki. Z zawodu jest autorką.","why":"*Sie* → forma żeńska z *-in*: *der Autor → die Autorin*. Po *sein … von Beruf* nie ma rodzajnika."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Dzieci nie odrabiają zadań domowych. Dlatego rodzice na nie krzyczą.","why":"*mit jemandem schimpfen* = besztać kogoś, krzyczeć na kogoś. Podmiot w liczbie mnogiej *die Eltern* → *schimpfen*. Po *Deshalb* czasownik stoi zaraz potem."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Pracuje dopiero od kilku miesięcy. Ma jeszcze niewielkie doświadczenie w zawodzie.","why":"*die Erfahrung* = doświadczenie. *wenig Erfahrung haben* = mieć niewielkie doświadczenie."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Teraz mamy chaos. Wszystko jest pomieszane.","why":"*durcheinander sein* = być w nieładzie, pomieszanym. Pisane łącznie."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Dla Ye-Jon głoski P i F brzmią tak samo. Nie potrafi ich rozróżnić.","why":"*unterscheiden* = rozróżniać. Z *kann* bezokolicznik idzie na koniec. *tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Na wakacje jadę do Grecji, ale niestety w ogóle nie mówię po grecku.","why":"*Griechisch* = język grecki, wielką literą. *kein Griechisch können* = w ogóle nie mówić po grecku."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"On je tylko warzywa i ryż. Je wyłącznie warzywa i ryż.","why":"*ausschliesslich* = wyłącznie, nic poza tym. Pisownia szwajcarska z *ss*; w Niemczech pisze się to z ostrym s (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Hasło (zaznaczony rząd w siatce): język ojczysty","why":"Każde słowo daje jedną literę zaznaczonego rzędu: stam**M**en, trenn**U**ng, schrif**T**, (T w siatce), veränd**E**rt, auto**R**in, (S w siatce), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"Jak w domu w kilku językach","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Moje najpiękniejsze niemieckie słowo","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Dopasuj każde zdjęcie do słowa z ramki. Kolorowe kropki w książce podają rodzajnik: niebieska = der, zielona = das, czerwona = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (deser: krem z karmelem)","why":"Szwajcarska nazwa crème caramel. *Chöpfli* to w szwajcarskim niemieckim „główka” (*Kopf*). Zielona kropka → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – spadająca gwiazda","why":"*der Stern* = gwiazda; *die Sternschnuppe* = spadająca gwiazda. Czerwona kropka → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – motyl","why":"Szwajcarskie słowo na *der Schmetterling* (motyl); Duden oznacza je *schweizerisch, sonst landschaftlich*. Niebieska kropka → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Dlaczego ktoś może uważać właśnie te słowa za najpiękniejsze? Co o tym myślisz? Zrób notatki, potem o nich porozmawiajcie. Przykładowe notatki to jedna z możliwości.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"takie kolorowe i lekkie, przypomina lato, zabawne: to zwierzę wcale nie jest ptakiem","why":"Pomyśl, co to słowo każe ci zobaczyć lub poczuć i jak brzmi."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"słodkie, przypomina dzieciństwo, brzmi zabawnie i typowo szwajcarsko","why":"*tönen* to szwajcarskie słowo na *klingen* (brzmieć)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantyczne, można sobie czegoś życzyć, brzmi miękko","why":"Wystarczą krótkie notatki: przymiotniki i powód."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Moje ulubione słowo","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Które niemieckie słowo i które słowo w twoim języku ojczystym lubisz? Dlaczego? Napisz krótki tekst, korzystając ze zwrotów. Przykładowa odpowiedź to jedna z możliwości.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Moje ulubione niemieckie słowo to „gemütlich” (przytulny, swojski). Kiedy słyszę to słowo, myślę o zimowym wieczorze z herbatą, świecami i przyjaciółmi. Dlatego wydaje mi się takie ładne. Brzmi miękko i ciepło. W moim języku ojczystym, angielskim, nie ma słowa o dokładnie takim znaczeniu. Po angielsku podoba mi się słowo „sunshine”. Dla mnie to radosne słowo, bo brzmi jasno i przyjaźnie.","why":"*Wenn …, dann* + czasownik zaraz potem (*denke ich*); *Deshalb* + czasownik zaraz potem (*finde ich*). Wstaw własny język ojczysty i własne słowa.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Przedstaw swój tekst na zajęciach. Możliwy początek pokazuje przykład.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Chciałbym wam dziś przedstawić moje ulubione słowo. To słowo „gemütlich”. …","why":"Zacznij od podania słowa, potem przeczytaj swój tekst z a. *euch* do kolegów z grupy, *Ihnen*, jeśli mówisz oficjalnie."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"słownik spójników grammis: wenn (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Grzeczne dopytywanie, nauka języków, szukanie pracy · test z lekcji 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (zdania warunkowe, także nierzeczywiste z Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"słownik spójników grammis: weil (podrzędny, czasownik na końcu)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"słownik spójników grammis: denn (przyczynowy, czasownik zostaje na drugim miejscu)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"słownik spójników grammis: deswegen (skutek; stoi przed czasownikiem lub w środku zdania)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"słownik spójników grammis: deshalb (skutek; synonimy daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"słownik spójników grammis: d(a)rum (skutek)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen z dopełniaczem)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Przepraszam, czy mógłby Pan to powtórzyć?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij każde pytanie lub zdanie początkiem z ramki. Każdy początek jest użyty raz; przekreślony jest użyty w przykładzie.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Co znaczy wyrażenie „es eilig haben”?","why":"*Was bedeutet …?* pyta o znaczenie słowa lub wyrażenia. (*es eilig haben* = spieszyć się.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Czy mógłby Pan mówić trochę wolniej?","why":"*Könnten Sie …* (Konjunktiv II) sprawia, że prośba jest grzeczna; bezokolicznik *sprechen* idzie na koniec.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Przepraszam, nie zrozumiałem tego słowa.","why":"Perfekt: *habe … verstanden*; *das Wort* stoi na początku dla podkreślenia, więc czasownik *habe* stoi zaraz po nim.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Słucham? Czy mógłby Pan to powtórzyć?","why":"Grzeczna prośba z *Könnten Sie …*; *wiederholen* (powtórzyć) idzie na koniec.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Czy wie Pani, czy są tu też kursy integracyjne?","why":"*ob* wprowadza zależne pytanie typu tak/nie, więc czasownik *gibt* idzie na koniec.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Przepraszam, czy dobrze to zrozumiałem?","why":"Pytanie typu tak/nie w czasie Perfekt: *habe* na początku, *verstanden* na końcu.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Czy mogłaby mi Pani powiedzieć, gdzie jest stołówka?","why":"Pytanie zależne z *wo*: czasownik *ist* idzie na koniec. *die Mensa* = stołówka uczelniana.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij dialogi. Wydrukowane pierwsze litery (i kilka liter w środku słów) są podane; wpisz całe brakujące słowa.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Słucham? Nie zrozumiałam ostatniego słowa.","why":"Perfekt: *habe* na drugim miejscu po *Das letzte Wort*, *verstanden* na końcu.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Przepraszam, tu jest tak głośno. Czy mogłaby Pani powtórzyć godzinę spotkania?","why":"Grzeczna prośba: *Könnten Sie* … bezokolicznik *wiederholen* na końcu. *der Termin* to tutaj godzina spotkania.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Czy mogę Pana o coś zapytać? – Tak, oczywiście. – Czy wie Pan, czy w pociągu do Genewy o 14.33 jest też bistro albo wagon restauracyjny?","why":"*Darf ich Sie etwas fragen?* grzecznie otwiera rozmowę; *ob* zaczyna zależne pytanie typu tak/nie, więc *gibt* idzie na koniec.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Ułóż słowa z sylab w ramce i uzupełnij zdania. Przekreślone sylaby (Men, sa) są użyte w przykładzie.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Mój samochód znowu się zepsuł. Czy mógłbyś mi jeszcze raz dać numer telefonu do twojego dobrego mechanika? Tym razem chcę go od razu zapisać w notesie z adresami, żeby znowu go nie zgubić.","why":"Me-cha-ni-ker (osoba, która naprawia samochody) i auf-schrei-ben (bezokolicznik na końcu po *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Co znaczy wyrażenie „eine Entscheidung treffen”? Nigdy go nie słyszałem.","why":"Aus-druck: *der Ausdruck* = wyrażenie; *der* i *Den* pokazują, że to rodzaj męski. (*eine Entscheidung treffen* = podjąć decyzję.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Niestety często zapominam ważne niemieckie słowa. Potrzebuję więcej czasu na powtórki.","why":"Wie-der-ho-lung: *zur* = *zu der*, więc dalej stoi rzeczownik rodzaju żeńskiego: *die Wiederholung* (powtórka, powtarzanie).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Nauka języków obcych – ale jak?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Nauka języków obcych – ale jak?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Kto co mówi? Przeczytaj trzy teksty i po każdym zdaniu napisz literę tekstu (A, B lub C).","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"Często słucham innych ludzi. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"W drodze do szkoły uczę się słówek. → A (Mila)","why":"Mila wyjmuje fiszki podczas godzinnej jazdy pociągiem do szkoły.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Po szkole chciałbym pracować w Anglii. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Oglądam dużo niemieckojęzycznej telewizji. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Piszę fiszki ze słówkami. → A (Mila)","why":"Mila pisze obce słowo po jednej stronie kartki, a tłumaczenie po drugiej.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Napisz drugie zdanie: zacznij od podanego słowa (Deshalb, Darum …) i użyj słów w nawiasach. Czasownik stoi zaraz po słowie na początku.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Dlatego powtarza nowe słówka za pomocą fiszek.","why":"*Darum* zajmuje pierwsze miejsce, więc zaraz po nim stoi odmieniony czasownik *wiederholt*, a potem podmiot *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Z tego powodu ma w smartfonie dużo podcastów.","why":"*Aus diesem Grund* zajmuje pierwsze miejsce tak jak *deshalb*: zaraz potem czasownik *hat*, potem *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Dlatego chce dobrze mówić po angielsku.","why":"*Deswegen* + czasownik modalny *will* na drugim miejscu, bezokolicznik *sprechen* na końcu.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Dlatego ogląda dużo niemieckojęzycznej telewizji.","why":"*Daher* znaczy to samo co *deshalb*; czasownik *schaut* stoi zaraz po nim.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Z tego powodu po prostu zawsze i wszędzie słucha Szwajcarów.","why":"*zuhören* jest czasownikiem rozdzielnie złożonym: *hört … zu*. Polecenie podaje *zugehört*, więc Perfekt *hat … zugehört* (jak w tekście Danili) też jest poprawny.","source":"hueber","check":"Oficjalny klucz podaje czas teraźniejszy (*hört … zu*), chociaż polecenie podaje imiesłów *zugehört*. Oba zdania są poprawne po niemiecku; zapytaj nauczyciela, którą wersję chce książka."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test z lekcji 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij tekst Arifa. Książka podaje pierwszą literę i kilka liter w środku każdego słowa; wpisz całe słowo.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… a naszym językiem ojczystym jest arabski.","why":"*die Muttersprache* = pierwszy język, z którym się dorasta."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Dlatego chciałbym poprawić swój niemiecki.","why":"Układ liter (D, e, e) pasuje do *Deswegen*; podaje skutek, a czasownik *möchte* stoi zaraz po nim.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Oczywiście nie będę wtedy jeszcze mówić płynnie po niemiecku.","why":"*fliessend* = płynny, płynnie. Pisownia szwajcarska z *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Szczególnie trudne wydają mi się pismo i wymowa …","why":"*die Aussprache* = wymowa (*aussprechen* = wymawiać)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… i też jeszcze nie rozumiem wszystkich wyrażeń.","why":"*der Ausdruck, die Ausdrücke* = wyrażenie, wyrażenia; *alle* wymaga liczby mnogiej."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Napisz nierzeczywiste zdania warunkowe z *wenn* i trybem przypuszczającym Konjunktiv II (*wäre, hätte, könnte, müsste* lub *würde* + bezokolicznik).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Gdyby mój angielski był lepszy, mógłbym ci pomóc w zadaniu domowym.","why":"*sein* → **wäre** na końcu zdania z *wenn*; *können* → **könnte**, potem zdanie główne zaczyna się od czasownika.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Lepiej bym was rozumiał, gdybyście nie mówili wszyscy naraz.","why":"Najpierw zdanie główne; *würde* + bezokolicznik w obu częściach. W zdaniu z *wenn* forma *würdet* idzie na koniec.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Miałbym więcej czasu wolnego, gdybym nie musiał tyle pracować.","why":"*haben* → **hätte**, *müssen* → **müsste** (na końcu zdania z *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij słowem z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie (odpowiedź do a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Dlaczego Costa chce zostać mechatronikiem? – Bo interesuje się samochodami.","why":"Potrzebny jest zaimek pytający; **Weshalb** = *warum* (dlaczego). Wydrukowana odpowiedź zaczyna się od *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Dzięki dobrej znajomości niemieckiego szybko znalazł miejsce nauki zawodu.","why":"Dalej stoi grupa rzeczownikowa (*seiner guten Deutschkenntnisse*, dopełniacz liczby mnogiej) → przyimek **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Ma dopiero 17 lat. Dlatego wciąż mieszka u rodziców.","why":"Skutek, a czasownik stoi zaraz po luce (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Teraz oszczędza pieniądze, bo po nauce zawodu chciałby mieć własne mieszkanie.","why":"Przyczyna, a czasownik zostaje na drugim miejscu (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"Jak inaczej można to powiedzieć? Uzupełnij drugi zwrot. Książka podaje kilka liter; wpisz całe słowa.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Mam pytanie. – Czy mogę Pana o coś zapytać?","why":"Grzeczny sposób, żeby zacząć pytanie: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Czy mógłby Pan to jeszcze raz powiedzieć? – Czy mógłby Pan to powtórzyć?","why":"*wiederholen* = powtórzyć = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Co ma Pan na myśli, mówiąc …? – Co znaczy …?","why":"*Was bedeutet …?* pyta o znaczenie, tak jak *Was meinen Sie mit …?*","check":"Litery w tej luce są na zdjęciu słabo czytelne; *Was bedeutet …?* do nich pasuje i jest zwrotem z ćwiczenia 13. Zapytaj nauczyciela, jeśli w twojej książce jest coś innego."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Przepraszam. – Przykro mi.","why":"*Tut mir leid* = przykro mi, inny sposób, żeby przeprosić."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Praca w centrum uwagi: szukanie pracy","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf szuka nowej pracy jako fryzjer. Czyta broszurę ze wskazówkami, jak szukać pracy. Przeczytaj wskazówki i po każdym akapicie napisz literę pasującego nagłówka (A–E).","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Akapit 1 (lista osób, które znasz) → C, Twoja osobista sieć kontaktów","why":"Przyjaciele, koledzy z pracy i byli pracodawcy to twoja osobista sieć kontaktów.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Akapit 2 (twoje własne ogłoszenie w internecie) → A, Ogłoszenie o szukaniu pracy w internecie","why":"*das Stellengesuch* = ogłoszenie, w którym szukasz pracy; tutaj na portalu internetowym.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Akapit 3 (krótkie podanie o pracę do wymarzonej firmy) → E, Aplikacja z własnej inicjatywy","why":"Zgłaszasz się do firmy, która nie ogłosiła oferty pracy: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Akapit 4 (ubieganie się o pracę przez telefon) → D, Ubieganie się o pracę przez telefon","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Akapit 5 (analiza ogłoszeń o pracę w internecie) → B, Ogłoszenia o pracę","why":"*das Stelleninserat* (szwajcarskie słowo) = ogłoszenie o pracę zamieszczone przez firmę.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf postanowił wziąć sprawy w swoje ręce i napisał ogłoszenie, że szuka pracy. Przeczytaj jego tekst i znajdź: kim jest Yusuf i jaki jest, co potrafi i czego szuka. Przy każdym pytaniu wypisz pasujące słowa.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"zaangażowany fryzjer, kreatywny i elastyczny, 24 lata","why":"Kim jest (zawód, wiek) i jaki jest (przymiotniki).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"sześć lat doświadczenia zawodowego, różne szkolenia z doradztwa w zakresie stylu","why":"Co oferuje: doświadczenie i szkolenia.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"wyzwanie, przy którym może nauczyć się nowych rzeczy i dalej się specjalizować","why":"Ostatnie zdanie: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Zamieść w internecie ogłoszenie o poszukiwaniu pracy. Szukasz nowej pracy. Zrób tabelę z trzema kolumnami (Kim jestem i jaki/jaka jestem? Co potrafię? Czego szukam?), potem napisz tekst profilu taki jak tekst Yusufa w 2. Przykładowa odpowiedź to jedna z możliwości.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Kim jestem i jaka jestem? elastyczna, umiejąca pracować w zespole, solidna, towarzyska | Co potrafię? dobrze obsługiwać klientów, dobra znajomość komputera, płynny niemiecki i angielski | Czego szukam? pracy na część etatu od przyszłego miesiąca, międzynarodowego zespołu","why":"Wystarczy kilka słów kluczowych w każdej kolumnie; użyj zwrotów z ramki.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Szukają Państwo solidnej sprzedawczyni, która umie pracować w zespole i jest towarzyska? Potrafię dobrze obsługiwać klientów, dobrze znam się na komputerach i mówię płynnie po niemiecku i angielsku. Od przyszłego miesiąca szukam pracy na część etatu w międzynarodowym zespole.","why":"Te same trzy kroki co u Yusufa: kim jesteś, co potrafisz, czego szukasz. *die* w zdaniu względnym odnosi się do *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Gramatyka","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Życzenie i rzeczywistość?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina musi zrobić jedno, ale wolałaby zrobić coś innego. Napisz, co wolałaby robić, używając *würde* + słów w nawiasach (z *lieber*, a w punkcie 5 z *gern*).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Ale wolałaby słuchać muzyki.","why":"*würde* na drugim miejscu, *lieber* = raczej, bezokolicznik *hören* na końcu.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Ale wolałaby porozmawiać przez telefon z przyjaciółką.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Ale wolałaby grać w gry komputerowe.","why":"*würde* + *lieber* + bezokolicznik na końcu.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Ale chętnie czytałaby do późnej nocy.","why":"Książka podaje *gern*: *würde* + *gern* + bezokolicznik (życzenie), z *aber* po czasowniku.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Ale wolałaby pójść potańczyć.","why":"*würde* + *lieber*; oba bezokoliczniki *tanzen gehen* na końcu.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Przepisz zdania z a jako nierzeczywiste zdania warunkowe: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Gdyby Nina nie musiała uczyć się do egzaminu językowego, słuchałaby muzyki.","why":"*muss* → **müsste** na końcu zdania z *wenn*; zdanie główne zaczyna się od *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Gdyby Nina nie musiała sprzątać swoich ubrań, rozmawiałaby przez telefon z przyjaciółką.","why":"*müsste* + bezokolicznik *aufräumen*: w zdaniu z *wenn* *müsste* stoi na końcu.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Gdyby Nina nie pracowała przy komputerze, grałaby w gry komputerowe.","why":"Klucz akceptuje w zdaniu z *wenn* zarówno *arbeiten würde*, jak i *arbeiten müsste*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Gdyby Nina nie miała jutro bardzo wcześnie umówionego spotkania, czytałaby do późnej nocy.","why":"*hat* → **hätte**, na końcu zdania z *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Gdyby Nina nie spędzała wieczoru z rodzicami, poszłaby potańczyć.","why":"*würde* + bezokolicznik w obu częściach; *verbringen würde* na końcu zdania z *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Uzupełnij słowem *darum*, *weil* lub *wegen*. Każde słowo jest użyte dwa razy.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Wielu Niemców nie słyszy błędów gramatycznych Majida, bo ma on bardzo dobrą wymowę.","why":"Przyczyna, a czasownik *hat* stoi na końcu → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko nie zdał egzaminu, dlatego chce teraz zrobić kurs intensywny.","why":"Skutek, a czasownik *will* stoi zaraz po luce → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan chce pracować jako lekarz w niemieckim szpitalu, dlatego potrzebuje bardzo dobrej znajomości niemieckiego.","why":"Skutek + czasownik zaraz po luce (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla jest menedżerką i z powodu wielu konferencji nie może regularnie chodzić na kurs niemieckiego.","why":"Dalej stoi grupa rzeczownikowa (*ihrer vielen Konferenzen*, dopełniacz liczby mnogiej) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Borisa z powodu akcentu od razu rozpoznaje się jako Rosjanina.","why":"Grupa rzeczownikowa w dopełniaczu (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja chętnie nauczyłaby się arabskiego, bo pismo arabskie wydaje jej się takie piękne.","why":"Przyczyna z czasownikiem *findet* na końcu → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Słownictwo","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij tekst Ferdeza słowami z ramki. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Karta pracy używa pisowni z Niemiec z ostrym s; tutaj jest pisownia szwajcarska z *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"W macedońskim używa się cyrylicy. Dlatego na początku nie było mi łatwo pisać po niemiecku.","why":"*die kyrillische Schrift* = cyrylica."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Od ośmiu lat mieszkam w Bawarii. Teraz mówię już płynnie po niemiecku, tak uważam.","why":"*fliessend Deutsch sprechen* = mówić płynnie po niemiecku."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Ale moi koledzy z północnych Niemiec mówią, że mam bawarski akcent!","why":"*einen … Akzent haben* = mieć akcent; *einen bayerischen* → rzeczownik rodzaju męskiego."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Kiedy klnę po bawarsku, moi koledzy pękają ze śmiechu.","why":"*schimpfen* = narzekać, kląć; *ich schimpfe* na końcu zdania z *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Kiedy porównuję ze sobą niemiecki, macedoński i albański, zauważam, …","why":"*miteinander vergleichen* = porównywać ze sobą; *ich vergleiche* na końcu zdania z *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… że nie wszystkie słowa da się naprawdę dobrze przetłumaczyć na drugi język. Dziś czuję się jak w domu i w Macedonii, i w Niemczech.","why":"*in eine Sprache übersetzen* = tłumaczyć na jakiś język; bezokolicznik przed *kann* na końcu zdania z *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Co znaczy przysłowie „Lügen haben kurze Beine“ (kłamstwa mają krótkie nogi)? Wpisz A lub B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: Prawda zawsze szybko wychodzi na jaw. Dlatego nie należy kłamać.","why":"Kłamstwo nie zajdzie daleko, jak ktoś na krótkich nogach: szybko wychodzi na jaw. B to żart z dosłownego znaczenia słów."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Które słowo z ramki mogłoby zastąpić podkreślone słowo? Napisz je. Każde słowo jest użyte raz; przekreślone jest użyte w przykładzie. Podkreślone słowa są tu pogrubione.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Ja sam urodziłem się jednak w Moguncji.","why":"*allerdings* = *aber*: ogranicza to, co powiedziano wcześniej."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Rodzice zawsze mówili do mnie po niemiecku, dlatego niestety nie znam farsi.","why":"*deswegen* = *deshalb* (skutek, czasownik stoi zaraz potem).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Teraz chodzę na kurs językowy. Uważam, że farsi jest tak samo trudny jak niemiecki.","why":"*ebenso … wie* = *genauso … wie* = tak samo … jak."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Zwłaszcza pismo! Jestem kimś, kto musi zapisywać wszystkie nowe słowa.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = zapisać coś sobie."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"To trudne, kiedy musisz to robić w piśmie, którego dopiero stopniowo się uczysz.","why":"*allmählich* = powoli, krok po kroku, stopniowo."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"Wymowa też nie jest łatwa. Jest taki dźwięk „gh”, którego nie umiem poprawnie wymówić.","why":"*korrekt* = *richtig* = poprawnie."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Kiedyś się uda – przynajmniej mam taką nadzieję!","why":"*irgendwann* = kiedyś, pewnego dnia = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Czytanie","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Przeczytaj odpowiedzi na ankietę „Czy nauka niemieckiego jest ważna?” i wybierz właściwe zakończenie każdego zdania. Wpisz zakończenie (albo tylko jego pierwsze słowa).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Kto dobrze zna angielski, i tak musi się dobrze nauczyć niemieckiego.","why":"Bradowi, dla którego angielski jest językiem ojczystym, w kółko powtarzano: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Niemcy najwyraźniej uważają, że bez perfekcyjnego niemieckiego nie ma się kwalifikacji zawodowych.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena ma nadzieję, że z certyfikatem z niemieckiego (Zertifikat Deutsch) znajdzie pracę w Austrii.","why":"Alena liczy na dobre szanse *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Jako Polka Ewa chce znać niemiecki, bo Niemcy i Polska mają wspólną historię.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa żałuje, że niewielu Niemców interesuje się językiem polskim.","why":"Ewa chciałaby, żeby więcej Niemców interesowało się polskim."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha nauczyła się niemieckiego od męża.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Ma problemy, bo nie rozumie wystarczająco dobrze nauczycieli.","why":"Z wychowawcą klasy i na zebraniach z rodzicami ma *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Do pozwolenia na pracę wymagana jest dobra znajomość niemieckiego.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah chce dobrze znać niemiecki, bo mieszka w Niemczech.","why":"Chce znać język *des Landes …, in dem ich lebe*; jego niemiecki już wystarcza do rozmów z pacjentami."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha uczy się niemieckiego ze względu na dzieci.","why":"Jej dzieci narzekały, że jej niemiecki jest taki słaby, a teraz pomagają jej się uczyć."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Mówienie","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Która odpowiedź pasuje najlepiej? Po każdym zdaniu wpisz numer odpowiedzi (1–6). (Ćwiczenie 6 na tej stronie to zadanie ze słuchania i zostało pominięte.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Nazywam się Kranitzky-Krampe. → 5 Przepraszam, jak brzmi Pana nazwisko?","why":"Długie, nietypowe nazwisko: dopytujesz."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Na ubrania można też powiedzieć „Klamotten”. → 4 Nigdy nie słyszałem tego słowa.","why":"Nowe (potoczne) słowo: *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Co znaczy to słowo? → 1 Niestety też nie wiem.","why":"Odpowiedź na pytanie, na które nie znasz odpowiedzi."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Naprawdę miałem wtedy szczęście. → 6 Czy dobrze zrozumiałem: miał Pan szczęście?","why":"*Schwein haben* (potocznie) = mieć szczęście; sprawdzasz, czy dobrze zrozumiałeś."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Czy mógłby Pan mówić trochę wolniej? → 3 Dobrze, postaram się.","why":"Odpowiedź na prośbę."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Napisz pytania zależne ze słowami w nawiasach. W pytaniu zależnym czasownik idzie na koniec.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Czy może mi Pan powiedzieć, dokąd mam zanieść śmieci?","why":"*wohin* zaczyna pytanie zależne; odmieniony czasownik *muss* idzie na koniec."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Czy może mi Pani powiedzieć, gdzie Panią boli?","why":"Pyta lekarz: *wo* + podmiot + czasownik na końcu (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Czy wie Pan może, czy ten pociąg jedzie do Berlina?","why":"Pytanie typu tak/nie staje się zależne z *ob*; czasownik *fährt* idzie na koniec."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Pisanie","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Wybierz język, którego chcesz się nauczyć, i napisz wiadomość do szkoły językowej: jaki język, kiedy i ile razy w tygodniu masz czas, w jakich terminach i godzinach są kursy, ile kosztuje kurs i jak długo trwa; poproś o odpowiedź i użyj odpowiedniego powitania i zakończenia. Przykładowa odpowiedź jest zgodna z oficjalnym kluczem.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Szanowni Państwo, chciałbym nauczyć się nowogreckiego. Mam czas od poniedziałku do czwartku wieczorami i mógłbym przychodzić dwa razy w tygodniu. Proszę o informację, w jakich godzinach oferują Państwo kurs języka nowogreckiego. Musiałbym też wiedzieć, ile kosztuje kurs i jak długo trwa. Proszę o krótką odpowiedź. Z poważaniem …","why":"List formalny: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Pytania są zależne (*zu welchen Zeiten …, wie viel …, wie lange …*): czasownik na końcu."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Bezokolicznik z zu, list motywacyjny, small talk o pracy · test z lekcji 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (czasowniki modalne bez zu; brauchen z zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (zdania bezokolicznikowe z zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu między przedrostkiem a czasownikiem: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (zdanie z dass lub zu + bezokolicznik)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (przyimek, z dopełniaczem)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (przyimki i przypadki, których wymagają)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Niestety nie mam czasu …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Uzupełnij każde zdanie czasownikiem z ramki. Każdy jest użyty raz; przekreślony jest użyty w przykładzie.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"Nie zapomnijcie, proszę, wyłączyć kuchenki.","why":"*ausschalten* jest rozdzielnie złożony, więc *zu* stoi między przedrostkiem a czasownikiem: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"Boję się być w nocy sam.","why":"*Angst haben* + *zu* + bezokolicznik; *sein* to czasownik prosty, więc *zu* stoi przed nim.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"Nie, działanie w klubie nie jest zbyt stresujące.","why":"*Es ist* + przymiotnik + *zu* + bezokolicznik. *mitarbeiten* jest rozdzielnie złożony: *mit**zu**arbeiten*. (Pierwsze *zu* znaczy tu „zbyt”.)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Niestety nie mam czasu, żeby wytłumaczyć Panu drogę.","why":"*keine Zeit haben* + *zu* + bezokolicznik. *erklären* nie jest rozdzielnie złożony (*er-* to przedrostek nierozdzielny), więc *zu* stoi przed nim.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Nie mam dziś ochoty pójść z wami na trening.","why":"*keine Lust haben* + *zu* + bezokolicznik; *mitkommen* jest rozdzielnie złożony: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Po jakich wyrażeniach stoi *zu*? Wpisz wyrażenie (czasownik albo czasownik + rzeczownik/przymiotnik), po którym w każdym zdaniu z a pojawia się *zu*.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"Nie zapomnijcie, proszę, wyłączyć kuchenki. → zapomnieć","why":"Po czasowniku *vergessen* (tu *Vergesst*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"Boję się być w nocy sam. → bać się","why":"Po *haben* + rzeczownik (*Angst, Lust, Zeit, Interesse*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"Nie, działanie w klubie nie jest zbyt stresujące. → (nie) jest zbyt stresujące","why":"Po *Es ist* + przymiotnik stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Niestety nie mam czasu, żeby wytłumaczyć Panu drogę. → (nie) mieć czasu","why":"Po *Zeit haben* (tu *keine Zeit*) stoi *zu* + bezokolicznik.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Nie mam dziś ochoty pójść z wami na trening. → (nie) mieć ochoty","why":"Po *Lust haben* (tu *keine Lust*) stoi *zu* + bezokolicznik.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Gdzie stoi *zu*? Tabela ma trzy kolumny: początek zdania, część środkową, potem czasownik z *zu*. Wstaw do niej zdania z a z czasownikiem rozdzielnie złożonym (2, 4, 6) i wpisz ostatnią kolumnę. Części czasownika są w nawiasach.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"Nie zapomnijcie, proszę, | kuchenki | wyłączyć.","why":"Czasownik rozdzielnie złożony: *zu* stoi między *aus* a *schalten* i całość pisze się jako jedno słowo.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"Nie, nie jest zbyt stresujące | w klubie | działać.","why":"Czasownik rozdzielnie złożony: *mit* + *zu* + *arbeiten*, pisane jako jedno słowo.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Nie mam dziś ochoty | na trening | pójść z wami.","why":"Czasownik rozdzielnie złożony: *mit* + *zu* + *kommen*, pisane jako jedno słowo.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Co jest poprawne? Wpisz *zu*, jeśli zdanie potrzebuje *zu*, albo *–* (myślnik), jeśli niczego nie potrzebuje.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Czy nie chciałby Pan też pracować w swoim wymarzonym zawodzie?","why":"Po czasowniku modalnym (*möchten*) bezokolicznik nigdy nie dostaje *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Mógłbym sobie dobrze wyobrazić, że uczę się jakiegoś rzemiosła.","why":"*sich vorstellen können* wprowadza po przecinku drugą część zdania z *zu* + bezokolicznik. *könnte* należy tylko do *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Z wykształceniem rzemieślniczym można znaleźć dobrą pracę.","why":"Czasownik modalny *kann* + bezokolicznik bez *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Czy mógłby mi Pan pomóc w wyborze zawodu?","why":"*Könnten* to czasownik modalny (Konjunktiv II od *können*): bez *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"Dowiadywanie się o możliwościach zawodowych jest dość stresujące.","why":"*Es ist* + przymiotnik (*stressig*) + *zu* + bezokolicznik.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Uzupełnij słowem *zu* albo wpisz *–* (myślnik) tam, gdzie niczego nie brakuje.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"Nie możemy zapomnieć o urodzinach szefowej!","why":"Czasownik modalny *dürfen* + bezokolicznik bez *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"Nie jest łatwo znaleźć posadę w wymarzonym zawodzie.","why":"*Es ist nicht leicht* + *zu* + bezokolicznik.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Najchętniej pracowałbym w zespole.","why":"*würde* + bezokolicznik (Konjunktiv II) działa jak czasownik modalny: bez *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Masz może chwilę, żeby pomóc mi przy podaniu o pracę?","why":"*Zeit haben* + *zu* + bezokolicznik.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Czy wyobrażasz sobie naukę zawodu w biurze?","why":"*Kannst* to czasownik modalny, więc nic nie wstawiasz: *vorstellen* pisze się jako jedno słowo.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Napisz zdania o swoim życiu zawodowym: połącz wyrażenie z lewej ramki z czynnością z prawej ramki. Przekreślone słowa są użyte w przykładzie. Przykładowa odpowiedź to jedna z możliwości.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"W życiu zawodowym nie chciałbym robić ciągle tego samego. Mam nadzieję, że będę pracować z miłymi kolegami. Uczenie się nowych rzeczy sprawia mi radość. Potrafię bardzo dobrze pracować samodzielnie. Męczące jest mieć mało wolnego czasu. Chętnie podróżowałbym przez pół roku po świecie.","why":"Po *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* używaj *zu* + bezokolicznik (czasowniki rozdzielnie złożone: *zusammen**zu**arbeiten*). Po *möchten, können, würde … gern* bez *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Dopasuj każdą wypowiedź do czasownika z ramki i napisz zdanie z *zu* + bezokolicznik. Przekreślony czasownik jest użyty w przykładzie.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Obiecuję, że jutro cię odbiorę.","why":"„Na pewno” = obietnica: *versprechen*. *abholen* jest rozdzielnie złożony: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"Mam zamiar znaleźć ciekawą pracę.","why":"Plan = *vorhaben*: *Ich habe vor, … zu finden.* Przedrostek *vor* idzie na koniec zdania głównego.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Mogę sobie wyobrazić, że uczę się jakiegoś rzemiosła.","why":"„Czemu nie?” = potrafisz to sobie wyobrazić: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"Pod koniec miesiąca przestaję pracować jako pielęgniarz.","why":"„Tylko do końca miesiąca” = przestać: *aufhören*, z *auf* na końcu zdania głównego, przed przecinkiem.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Znajdź w diagramie literowym dziewięć kolejnych słów i wstaw je do ogłoszeń o pracę A–C. Zakreślone słowa (*Bewerbung, Tätigkeit*) to przykłady. Wpisz każde słowo w formie, jakiej wymaga zdanie (rzeczowniki wielką literą).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Szukamy wsparcia do przewozu pacjentów na 15 godzin tygodniowo.","why":"*die Unterstützung* = wsparcie, pomoc; tu oznacza osobę, która pomaga.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Warunkiem podjęcia tej pracy jest: prawo jazdy kategorii B","why":"*die Voraussetzung* = wymaganie, warunek. *der Führerausweis* to szwajcarskie słowo na prawo jazdy.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ znajomość zasad pierwszej pomocy","why":"*Kenntnisse in* + celownik = znajomość czegoś / umiejętności w jakiejś dziedzinie.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"Na Pana / Panią czekają: ciekawe zadania, możliwości dokształcania, przyjemna atmosfera w pracy","why":"*Es erwarten Sie …* = „czekają na Pana / Panią …”; *es* zajmuje tylko pierwsze miejsce, a czasownik zgadza się z podmiotem w liczbie mnogiej, który stoi dalej.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ ciekawe zadania","why":"*die Aufgabe, die Aufgaben* = zadanie, zadania; *interessante* pokazuje liczbę mnogą.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Doświadczenie w handlu i sprzedaży będzie atutem.","why":"*der Handel* = handel, sprzedaż detaliczna; *im* = *in dem*. *von Vorteil* = atut, zaleta.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"W razie pytań prosimy zwrócić się pisemnie lub telefonicznie do pani Kleinert.","why":"*schriftlich oder telefonisch* = pisemnie lub telefonicznie.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Lubisz pracować z drewnem?","why":"*sich beschäftigen mit* = zajmować się czymś; *du beschäftigst dich*. To słowo zaczyna pytanie tak/nie, więc pisze się je wielką literą.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Wyślij swoje dokumenty aplikacyjne jeszcze dziś do: Clemens Meier","why":"*die Bewerbungsunterlagen* (liczba mnoga) = CV, świadectwa i list razem.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Uzupełnij właściwą formą *brauchen* lub *müssen*. Wskazówka: *brauchen* łączy się z *zu* + bezokolicznik oraz z przeczeniem albo z *nur*; *müssen* nigdy nie łączy się z *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"Twoje świadectwo jest przecież takie dobre. Naprawdę nie musisz się martwić o pracę.","why":"Przeczenie (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Jeśli pracuje tylko na część etatu, to nie musi cały dzień siedzieć przy komputerze.","why":"Bezokolicznik *sitzen* nie ma *zu*, więc czasownik to *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Jeśli chcemy wyjechać na trzy miesiące za granicę, to musimy teraz dużo oszczędzać.","why":"Bez *zu* i bez przeczenia: to obowiązek, więc *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"Moja wymarzona praca. Napisz zdania z *brauchen … zu* + bezokolicznik (= nie musieć / musieć tylko).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"Nie muszę wykonywać nudnych zadań.","why":"*brauchen* na drugim miejscu, *zu übernehmen* na końcu. *übernehmen* nie jest tu rozdzielnie złożony, więc *zu* stoi przed nim.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"Nie muszę robić nadgodzin.","why":"*keine* + *brauchen … zu* = brak obowiązku.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Muszę pracować tylko wtedy, kiedy mam na to ochotę.","why":"*nur brauchen … zu* = musieć tylko. *zu arbeiten* zamyka zdanie główne przed zdaniem z *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"Nie muszę współpracować z niemiłymi kolegami.","why":"*zusammenarbeiten* jest rozdzielnie złożony: *zusammen**zu**arbeiten*, jedno słowo.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"List motywacyjny","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Przeczytaj części listu i ułóż je we właściwej kolejności: wpisz numer (1–8) każdej części. Części są tu oznaczone literami A–H w kolejności, w jakiej drukuje je książka; B to przykład.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"Łatwo przychodzi mi uczenie się nowych rzeczy. Poza tym lubię doradzać klientom. Dlatego chętnie pracowałbym u Państwa jako sprzedawca. → 5","why":"To, dlaczego chcesz tę pracę, pojawia się po doświadczeniu (4), a przed końcową prośbą (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Z poważaniem / Tibor Kelemen → 7","why":"Pozdrowienie końcowe i twoje imię i nazwisko stoją po ostatnim zdaniu.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"Z dużym zainteresowaniem przeczytałem Państwa ogłoszenie i ubiegam się o wolne stanowisko sprzedawcy rowerów elektrycznych. → 3","why":"Pierwsze zdanie po powitaniu mówi, o jaką pracę się ubiegasz.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Byłbym wdzięczny za zaproszenie na rozmowę kwalifikacyjną. → 6","why":"Standardowe ostatnie zdanie listu motywacyjnego.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Załączniki: CV, świadectwa pracy → 8","why":"*Beilagen* (załączniki) są na samym końcu, pod nazwiskiem.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Szanowni Państwo → 2","why":"Powitanie stoi po temacie listu. W Szwajcarii nie stawia się po nim przecinka.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Jak wynika z moich dokumentów, po ukończeniu szkoły średniej (Sekundarschule) odbyłem naukę zawodu mechanika rowerowego w firmie „Velo-XL”. Potem przez dwa lata pracowałem jako pracownik w sklepie rowerowym i zdobyłem też pierwsze doświadczenia w sprzedaży. → 4","why":"Twoje wykształcenie i doświadczenie są po zdaniu otwierającym.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Zacznij wreszcie pisać podania o pracę!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Uzupełnij list motywacyjny. Pomoc znajdziesz w a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Szanowna Pani","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: końcówka zależy od osoby.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"Z dużym zainteresowaniem przeczytałam Państwa ogłoszenie o pracę i ubiegam się o stanowisko fizjoterapeutki.","why":"Stały zwrot otwierający z a; zajmuje pierwsze miejsce, więc zaraz po nim stoi czasownik *habe*.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Jak wynika z moich dokumentów, po szkole fizjoterapii pracowałam w Polsce przez cztery lata w szpitalu w Łodzi.","why":"*etwas (Dativ) entnehmen* = dowiedzieć się czegoś z czegoś: *meinen Unterlagen* to celownik liczby mnogiej.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Następnie przez dwa lata pracowałam w gabinecie Kunz & Rosenthal. Tam mogłam też zdobyć doświadczenie w dziedzinie medycyny sportowej.","why":"*Erfahrungen sammeln* = zdobywać doświadczenie.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"Moim językiem ojczystym jest polski. Ale mówię też bardzo dobrze po niemiecku i po angielsku.","why":"*die Muttersprache* = język ojczysty; *meine*, bo to rzeczownik rodzaju żeńskiego.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"Praca w domu opieki to dla mnie coś zupełnie nowego. Uczenie się nowych rzeczy sprawia mi dużą radość. Poza tym lubię troszczyć się o innych ludzi i cieszę się na kontakt z mieszkańcami.","why":"*Es macht mir Freude, … zu* + bezokolicznik, jak w a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Byłabym wdzięczna za zaproszenie na rozmowę kwalifikacyjną.","why":"Stałe zdanie końcowe: *eine Einladung zu* + celownik.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Z poważaniem Alina Jankowska","why":"Pozdrowienie końcowe; szwajcarska pisownia *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Wybierz jedno z trzech ogłoszeń o pracę z cyrku Tortellini (Zirkus Tortellini) i napisz list motywacyjny. Wykorzystaj części z a i b. Przykładowa odpowiedź to jedna z możliwości.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Podanie o pracę na stanowisko akrobatki / Szanowny Panie / Z dużym zainteresowaniem przeczytałam Pana ogłoszenie o pracę i ubiegam się o stanowisko akrobatki w Pana cyrku. Jak wynika z moich dokumentów, ukończyłam szkołę tańca. Następnie przez trzy lata tańczyłam w teatrze w Bernie i zdobyłam tam pierwsze doświadczenia na scenie. Występowanie przed publicznością sprawia mi dużą radość. Dobrze mogę sobie wyobrazić podróżowanie z Pana cyrkiem po Szwajcarii. Byłabym wdzięczna za zaproszenie na rozmowę kwalifikacyjną. / Z poważaniem / Lara Steiner / Załączniki: CV, świadectwo pracy","why":"Te same osiem części co w a; każda odpowiada na jeden punkt ogłoszenia (wykształcenie tancerki, pierwsze doświadczenia w teatrze). *auf**zu**treten*: *auftreten* jest rozdzielnie złożony.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"W ostatnim roku szkoły …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Uzupełnij słowem *während* (podczas), *innerhalb* (w ciągu) lub *ausserhalb* (poza) oraz słowem z nawiasu we właściwej formie. Wszystkie trzy łączą się z dopełniaczem.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Dziękujemy za Pana zgłoszenie. Odpowiedź otrzyma Pan w ciągu kilku tygodni.","why":"Granica czasowa = *innerhalb*; dopełniacz liczby mnogiej bez rodzajnika: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Dzwonią Państwo poza naszymi godzinami pracy. Są one od …","why":"Poza jakimś przedziałem czasu = *ausserhalb*; dopełniacz liczby mnogiej *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"W czasie oczekiwania może się Pan śmiało poczęstować kawą.","why":"W tym samym czasie co = *während*; dopełniacz rodzaju żeńskiego *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"Firma chce w ciągu najbliższych dwóch lat poprawić swoje wyniki o 20%.","why":"Granica czasowa = *innerhalb*; dopełniacz liczby mnogiej *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij wywiad przyimkami czasu z ramki. Każdy jest użyty raz; *während* jest w ramce dwa razy. Przekreślone *von … an* jest użyte w przykładzie.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"Technika zawsze mnie interesowała. Już w czasie szkoły pracowałam u elektryka.","why":"*während* + dopełniacz (*meiner Schulzeit*) = podczas.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Zaraz po szkole odbyłam praktykę w dużym przedsiębiorstwie energetycznym.","why":"*nach* + celownik (*der Schule*) = po.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Ale już podczas pierwszego roku poznaje się najważniejsze rzeczy.","why":"*während* + dopełniacz *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Przed egzaminem końcowym muszę jednak jeszcze dużo się nauczyć.","why":"*vor* + celownik (*der Abschlussprüfung*) = przed; wielka litera na początku zdania.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Od rana do końca dnia pracy jeżdżę po terenie naszego przedsiębiorstwa i naprawiam urządzenia.","why":"*von … bis* = od … do; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"Jakie doświadczenia masz jako kobieta w swojej pracy?","why":"*bei* + celownik (*deiner Arbeit*) = w trakcie, przy.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Tylko pozytywne! Z kolegami często spotykamy się wieczorami, czyli poza godzinami pracy.","why":"*ausserhalb* + dopełniacz (*der Arbeitszeit*) = poza.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Ćwiczenie egzaminacyjne: przeczytaj e-mail i uzupełnij luki 1–6. Która opcja (a, b lub c) pasuje najlepiej? Wpisz słowo (albo jego literę).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Dziękujemy za Pana zgłoszenie na stanowisko mechatronika samochodowego.","why":"*Vielen Dank für* + biernik.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Cieszymy się z Pana zainteresowania naszą firmą …","why":"*Interesse an* + celownik = zainteresowanie czymś; *Ihr* pasuje do rodzaju nijakiego *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Prosimy dać nam znać w ciągu najbliższych dni, …","why":"Granica czasowa z dopełniaczem (*der nächsten Tage*) = *innerhalb*. *bis* wymagałoby *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"…, czy może Pan przyjść w tym terminie.","why":"Pytanie zależne typu tak/nie wymaga *ob* (czy).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Prosimy przynieść również następujące dokumenty: oryginał świadectwa ukończenia szkoły zawodowej i Pana certyfikat B2.","why":"Świadectwo i dyplom to *Dokumente*; *Zeugnisse* nie obejmowałoby też certyfikatu B2, a *Sachen* jest zbyt ogólne jak na oficjalny list.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"W razie pytań i w sprawie dalszych informacji chętnie pozostajemy do Pana dyspozycji.","why":"Stały zwrot: *jemandem zur Verfügung stehen* = być do czyjejś dyspozycji.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"W ostatnim roku szkoły …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Dopasuj każde pytanie lub uwagę z rozmowy kwalifikacyjnej do odpowiedzi (1–7). Wpisz numer. (Ćwiczenie 13 to zadanie ze słuchania i zostało pominięte.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Proszę nam coś o sobie opowiedzieć. → 7 No więc jestem mechanikiem maszyn budowlanych i robię prawo jazdy kategorii BE.","why":"Przedstawiasz się: twój zawód i to, co teraz robisz.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"Jakie zadania miał Pan u swojego ostatniego pracodawcy? → 1 Odpowiadałem za kontrolę artykułów gospodarstwa domowego, ogrodowych i rekreacyjnych.","why":"*zuständig sein für* = odpowiadać za coś (twoje zadania).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Czy ma Pan jeszcze inne umiejętności? → 6 Tak, mówię w trzech językach.","why":"Pytanie tak/nie o umiejętności: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Czy może mi Pan powiedzieć więcej o swoich umiejętnościach komputerowych? → 2 Znam popularne programy, a w zeszłym roku zrobiłem kurs doszkalający z magazynowych baz danych.","why":"*beherrschen* = opanować, biegle znać; *sich weiterbilden* = dokształcać się.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Czy ma Pan jeszcze jakieś pytanie? → 3 Tak, chciałbym wiedzieć, jak duży jest tutaj magazyn.","why":"Pytanie zależne: *wie gross das Lager hier ist* (czasownik na końcu).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Dziękujemy bardzo, że Pan do nas przyszedł, panie Trantow. → 4 Ja również dziękuję.","why":"Odwzajemniasz podziękowanie: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"Potrafię to! Uzupełnij zdania informacjami o sobie. Przykładowe odpowiedzi to jedna z możliwości.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Już w czasie szkoły dorabiałem w kawiarni.","why":"*während* + dopełniacz; czas przeszły Perfekt z imiesłowem na końcu.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"Odpowiadałem za księgowość w małym biurze.","why":"*zuständig für* + biernik.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Biegle obsługuję Excela i popularne programy biurowe.","why":"*beherrschen* + biernik = opanować umiejętność lub język.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"Mam też bardzo dobrą znajomość angielskiego i włoskiego.","why":"*Kenntnisse in* + celownik.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Łatwo przychodzi mi praca w zespole i nawiązywanie kontaktu z nowymi klientami.","why":"*Es fällt mir leicht* + *zu* + bezokolicznik; *zugehen* jest rozdzielnie złożony: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Doradztwo zawodowe","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"Co jest prawdą? Przeczytaj teksty. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline nie ma ochoty studiować. → prawda","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Uważa, że trudno jest coś zaplanować lub zorganizować. → fałsz","why":"Jest odwrotnie: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"W przyszłym tygodniu chce się dowiedzieć czegoś o nauce zawodów handlowo-biurowych. → prawda","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, w sprawie zawodu handlowo-biurowego.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos planował po szkole pracować w dziedzinie techniki. → prawda","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"Na początku trudno mu było połączyć swoje zainteresowania. → prawda","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Spodziewał się, że nauka zawodu kreślarza architektury krajobrazu będzie mu sprawiać radość. → fałsz","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = nie spodziewał się tego.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Do każdego hasła (a–e) napisz zdanie z *zu* + bezokolicznik. Potem znajdź pasującą radę (1–5); rozwiązanie podaje jej numer.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"Nie uważam, żeby wczesne wstawanie było trudne. → 4 A może praca piekarza?","why":"*Ich finde es* + przymiotnik + *zu* + bezokolicznik; *aufstehen* jest rozdzielnie złożony: *auf**zu**stehen*. Piekarze zaczynają pracę bardzo wcześnie.","source":"g4069","check":"Oficjalny klucz podaje *Es fällt mir nicht schwer, früh aufzustehen*, co znaczy to samo; polecenie *es nicht schwer finden* daje *Ich finde es nicht schwer, …*. Oba zdania są poprawne."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"Mam ochotę często być w drodze. → 1 Mógłbyś zostać kierowcą autobusu.","why":"*Lust haben* + *zu* + bezokolicznik.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"Gotowanie dla innych sprawia mi radość. → 5 Na twoim miejscu zostałbym kucharzem.","why":"*Es macht mir Freude* + *zu* + bezokolicznik.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Interesuje mnie tworzenie nowych rzeczy. → 3 Hmm, trudne. Może projektant mody?","why":"*Interesse haben (daran)* + *zu* + bezokolicznik; *daran* zapowiada grupę z *zu*.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Słowa z -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Utwórz od czasowników rzeczowniki zakończone na *-ung*, z rodzajnikiem. (Części b–d to zadania ze słuchania i zostały pominięte.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"doświadczać → doświadczenie","why":"Temat czasownika + *-ung*; rzeczowniki na *-ung* są zawsze rodzaju żeńskiego: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"odpowiadać za → odpowiedzialność","why":"Temat *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"zatrudniać / zajmować → zatrudnienie, zajęcie","why":"Temat *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"wspierać → wsparcie","why":"Temat *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk: rozmowa o pracy","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij rozmowę towarzyską między Bettiną (○) a jej znajomym (◆) zwrotami z dwóch ramek (pokazanych tu jako jedna). Każdy zwrot jest użyty raz; przekreślony jest użyty w przykładzie.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Trudno. Wciąż szukam pracy jako tłumaczka.","why":"Po *Ich* stoi czasownik *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ Napisałam już kilka podań, ale dostałam same odmowy.","why":"Czas przeszły Perfekt: *habe … geschrieben*, pasuje do *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Nigdy nie myślałaś o tym, żeby założyć własną działalność? Przecież wielu tłumaczy tak robi.","why":"*daran denken* + *zu* + bezokolicznik; *daran* zapowiada grupę z *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Tak, to prawda. Ale ciągłe szukanie zleceń jest strasznie stresujące. Poza tym jest duża konkurencja.","why":"*Es ist* + przymiotnik + *zu* + bezokolicznik.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Ale co u ciebie? Wciąż masz tyle pracy?","why":"Odpowiedź *Ja, leider* wymaga pytania tak/nie.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Tak, niestety. W naszej firmie kilka osób jest teraz na zwolnieniu. Muszę zastępować dwóch kolegów. I to akurat teraz, kiedy mamy tyle zleceń!","why":"*vertreten* = zastępować kogoś.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ A czym ty się właściwie teraz dokładnie zajmujesz?","why":"Pytanie ze słowem pytającym na W (W-Frage): *Was* + czasownik *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Czy to nie jest męczące, ciągle jeździć z budowy na budowę?","why":"*Ist das nicht anstrengend, … zu* + bezokolicznik?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ Czasem tak, ale przeważnie praca sprawia mi radość. Dobrze dogaduję się z klientami i z kolegami. À propos, moja firma szuka właśnie kogoś do biura. Nie chcesz złożyć podania?","why":"*mit jemandem gut zurechtkommen* = dobrze dogadywać się z kimś (czasownik rozdzielnie złożony).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ No co ty! Jestem tłumaczką. Nie interesuje mnie praca sekretarki.","why":"*Interesse an* + celownik (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ Dobrze, zrobię tak. Dzięki za radę. Och, niestety muszę już iść.","why":"Typowy sposób na zakończenie small talku.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij krótkie ogłoszenia. Książka podaje kilka liter każdego słowa; wpisz całe słowo.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Praca dorywcza w przerwie semestralnej – szukamy cię jako tłumacza / tłumaczki krótkich tekstów reklamowych.","why":"*der Übersetzer / die Übersetzerin* = tłumacz / tłumaczka.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Praca na własny rachunek jako pomoc do sprzątania: na Putzfee.net może Pan / Pani zaoferować swoje usługi i szukać zleceń.","why":"*der Auftrag, die Aufträge* = zlecenie, zlecenia; *nach* + celownik liczby mnogiej dodaje *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Proszę zrobić kurs doszkalający. Oferujemy ciekawe seminaria z zakresu techniki i handlu.","why":"*eine Fortbildung machen* = dokształcać się, zrobić kurs doszkalający.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Bo konkurencja nie śpi!","why":"*die Konkurrenz* = konkurencja (rywale).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Elastyczni i zmotywowani? Szukamy osób, które mogą na godziny zastępować naszych pracowników magazynu.","why":"Czasownik modalny *können* + bezokolicznik *vertreten* (bez *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test z lekcji 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij zdania. Książka podaje kilka liter każdego słowa; wpisz całe słowo.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"Firma Müller & Müller jest bardzo dobra i dlatego ma dużo zleceń.","why":"*der Auftrag, die Aufträge* = zlecenie, zlecenia; *viele* wymaga liczby mnogiej."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"Pani Brügger odpowiada za 200 pracowników.","why":"*die Verantwortung für* + biernik = odpowiedzialność za coś."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"Firma produkuje meble ze szwajcarskiego drewna.","why":"*herstellen* = produkować, wytwarzać; rozdzielnie złożony: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario pracuje jako kelner w restauracji.","why":"*der Serviceangestellte* = kelner (użycie szwajcarskie); po *als* bez rodzajnika końcówka to *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter odpowiada za kontrolę i naprawę obrabiarek.","why":"*zuständig sein für* = odpowiadać za coś."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"Firma Müller & Müller oferuje swoim pracownikom wiele szkoleń.","why":"*die Fortbildung, die Fortbildungen*; *viele* wymaga liczby mnogiej."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Przepisz każde zdanie, zaczynając od podanego początku i używając *zu* + bezokolicznik. Wpisz tylko część po przecinku.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"Współpraca z kolegami sprawia mi radość.","why":"*die Zusammenarbeit* → czasownik *zusammenarbeiten*, rozdzielnie złożony: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Mógłbym sobie dobrze wyobrazić pracę jako pielęgniarz.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"Doradca zawodowy obiecuje pomóc w wyborze zawodu.","why":"*die Hilfe* → czasownik *helfen*: *zu helfen* na końcu.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Uzupełnij słowem *während*, *innerhalb* lub *ausserhalb* oraz rodzajnikiem we właściwej formie (dopełniacz). Książka podaje pierwszą literę rodzajnika.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"W trakcie rozmowy może Pan oczywiście śmiało zadawać pytania.","why":"*während* + dopełniacz rodzaju nijakiego: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Proszę dać znać w ciągu tygodnia, czy Pan przyjdzie.","why":"*innerhalb* + dopełniacz rodzaju żeńskiego: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Może się Pan ze mną skontaktować telefonicznie albo, poza godzinami pracy biura, mailowo.","why":"*ausserhalb* + dopełniacz liczby mnogiej: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Dopasuj każde pytanie do odpowiedzi (1–5). Wpisz numer.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Nigdy nie myślałeś o tym, żeby zmienić pracę? → 1 Nie, nie wyobrażam sobie tego.","why":"Pytanie o pomysł: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"Czym ty się właściwie teraz zajmujesz? → 4 Właśnie kończę naukę zawodu malarza.","why":"Pytanie ze słowem pytającym na W o twoją pracę wymaga odpowiedzi z konkretnym faktem."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Czy praca w nocy nie jest stresująca? → 2 Nie, nie uważam tak.","why":"*Ist es nicht stressig …?* pyta o opinię: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Wciąż masz tyle pracy? → 3 Tak, muszę zastępować koleżankę.","why":"Pytanie tak/nie; powód, dla którego jest tyle pracy: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Praca w centrum uwagi: negocjacje","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Cztery dobre wskazówki","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"Do czego służą te wskazówki? Przejrzyj tekst i wpisz właściwą odpowiedź. (Ćwiczenia 2 i 3 na tej stronie to zadania ze słuchania i zostały pominięte.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Do rozmów z pracodawcą","why":"Wskazówki dotyczą rozmowy o pieniądzach na rozmowie kwalifikacyjnej, z szefową lub szefem działu personalnego.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Co jest prawdą? Przeczytaj jeszcze raz. Po każdym zdaniu wpisz *richtig* (prawda) lub *falsch* (fałsz); w książce zaznaczasz tylko prawdziwe.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"Poruszenie tematu wynagrodzenia to zadanie szefowej / szefa działu personalnego. → prawda","why":"Wskazówka 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"W nowym miejscu pracy dostaje Pan / Pani na początku takie samo wynagrodzenie jak w starej firmie. → fałsz","why":"Wskazówki 2 i 3: twoje ostatnie wynagrodzenie to tylko punkt wyjścia; możesz poprosić o więcej.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Jeśli chce Pan / Pani zarabiać więcej, warto podać na to dobre argumenty. → prawda","why":"Wskazówka 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Jeśli szefowa / szef działu personalnego nie zgadza się z Pana / Pani propozycją, nic więcej nie da się zrobić. → fałsz","why":"Wskazówka 4: bądź elastyczny i zaproponuj coś innego (opłacone szkolenie, wyższe wynagrodzenie po sześciu miesiącach).","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"Cel z um … zu i damit, zamiast / bez, czasowniki z es, rozmowy w sklepie i reklamacje · test do Lektion 6","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Nie jest łatwo, ale warto.","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"Uzupełnij e-mail Anny wyrażeniami z *es* z ramki. Każde jest użyte raz; *geht es* jest użyte w przykładzie. Gdy w wyrażeniu jest *…*, pomiędzy stoją inne słowa: wpisz obie części w dwie luki.","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"Jest lato, wszędzie widać kwiaty i dużo przebywam na dworze. Uwielbiam tę porę roku!","why":"*es* + *sein* + pora roku albo pora dnia: *Es ist Sommer / Nacht / vier Uhr*.","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"Co prawda od kilku dni pada, ale zła pogoda mi przecież nie przeszkadza.","why":"Czasowniki pogodowe zawsze mają *es* jako podmiot. *Seit ein paar Tagen* stoi na pierwszym miejscu, więc *es* idzie po czasowniku: *regnet es*.","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"Najważniejsze, że nie jest zimno.","why":"Pogoda z przymiotnikiem: *es ist kalt / heiss*. *nicht* stoi przed *kalt*.","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"Słuchaj, miałam dziś przed południem rozmowę kwalifikacyjną! To było naprawdę ekscytujące, …","why":"Ogólne *es* + *sein* + przymiotnik, tutaj w czasie przeszłym Präteritum: *Es war aufregend*.","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"… ale właściwie poszło całkiem dobrze. Ludzie są bardzo mili, a praca jest urozmaicona.","why":"*Es ist gut gelaufen* = poszło dobrze (Perfekt z *sein*). *eigentlich* stoi na pierwszym miejscu, więc *ist es*.","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"Niestety jest tylko jeden problem: mam zaczynać pracę rano o 7 (!). Okropne!","why":"*es gibt* + biernik = jest / są: *Es gibt ein Problem*.","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"Przecież wiesz, jak trudno mi wcześnie wstawać.","why":"*Es fällt mir schwer, … zu …* = trudno mi … W zdaniu z *wie* czasownik idzie na koniec: *wie schwer es mir fällt*.","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"Zwłaszcza zimą, kiedy jest jeszcze ciemno, …","why":"*Es ist dunkel* (pora dnia, światło). W zdaniu z *wenn* czasownik idzie na koniec: *wenn es noch dunkel ist*.","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"… wtedy robi się dla mnie naprawdę trudno.","why":"*Es wird schwierig* = robi się trudno. *dann* stoi na pierwszym miejscu, więc *wird es*.","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"Co prawda bardzo mi się w tej firmie podobało, ale nie wiem, czy dam radę z tym wczesnym wstawaniem. Co mi radzisz?","why":"*Es gefällt mir* = podoba mi się; Perfekt: *Es hat mir gefallen*. Tutaj na pierwszym miejscu stoi *Mir*.","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"P.S.: O rany, znowu jest już pierwsza w nocy.","why":"Godzina: *Es ist ein Uhr*. *jetzt* stoi na pierwszym miejscu, więc *ist es*.","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"Może powinnam po prostu kłaść się wcześniej spać? Kto wie, może to się opłaci i nagle rano zawsze będę w świetnej formie?","why":"*Es lohnt sich* = to się opłaca, warto. *vielleicht* stoi na pierwszym miejscu, więc *lohnt es sich*.","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"Podziel wyrażenia z *es* z ćwiczenia 1 na cztery grupy. Wpisz grupę: *Allgemein* (ogólne), *Tages-/Jahreszeiten* (pory dnia i pory roku), *Wetter* (pogoda) albo *Befinden* (samopoczucie).","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"Jest lato. → pory dnia i pory roku","why":"Pora roku.","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"pada deszcz → pogoda","why":"Czasownik pogodowy.","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"jest zimno → pogoda","why":"Temperatura to pogoda.","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"Było (ekscytująco) → ogólne","why":"*es* + *sein* + przymiotnik opisujący sytuację.","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"poszło (dobrze) → ogólne","why":"Jak coś poszło: wyrażenie ogólne.","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"Jest / są → ogólne","why":"*es gibt* = jest / są.","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"jak trudno mi jest → ogólne","why":"*es fällt mir schwer* = trudno mi.","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"jest ciemno → pory dnia","why":"Ciemno = pora dnia.","source":"hueber","check":"Oficjalny klucz zalicza *es ist dunkel* do pór dnia. Można to też uznać za pogodę; zapytaj nauczyciela, jeśli w twojej klasie przyporządkowaliście to inaczej."},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"robi się trudno → ogólne","why":"*es* + *werden* + przymiotnik opisujący sytuację.","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"podobało mi się → ogólne","why":"*es gefällt mir* = podoba mi się.","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"jest pierwsza → pory dnia","why":"Godzina.","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"to się opłaca → ogólne","why":"*es lohnt sich* = to się opłaca, warto.","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"Gdzie brakuje *es*? Przeczytaj e-mail Fatimy. Każde zdanie poniżej napisz jeszcze raz z *es* we właściwym miejscu. Jedno zdanie jest poprawne: wtedy wpisz je bez zmian.","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"Mam nadzieję, że u was wszystko dobrze.","why":"*Wie geht es euch?* → *dass es euch gut geht*: *es* jest w tym znaczeniu podmiotem *gehen* i nie można go pominąć.","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"Odkąd mieszkamy w Gossau, dużo się wydarzyło.","why":"Bez *es*: podmiotem jest *viel*, a zdanie z *seit* zajmuje pierwsze miejsce.","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"Teraz idzie całkiem dobrze, ale na początku było dużo problemów.","why":"Dwie luki: *es läuft gut* (sprawy idą dobrze) i *es gab* (było / były, Präteritum od *es gibt*). Gdy na pierwszym miejscu stoi *jetzt* / *am Anfang*, *es* idzie po czasowniku.","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"Dla naszych dzieci było szczególnie trudno.","why":"*es* + *sein* + przymiotnik: *es war schwer*.","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"Ale teraz jest już dużo lepiej i przyzwyczaiły się do tutejszego życia.","why":"*es ist besser*: sytuacja nie ma innego podmiotu, więc *es* jest potrzebne.","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"No dobrze, zaraz będzie 9.","why":"Godzina: *es ist 9 Uhr*.","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"Nie jest łatwo, ale warto.","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Co jest poprawne? Przeczytaj tekst o spotkaniu mieszkańców wsi i wpisz słowo, które pasuje do każdej luki. Dwie możliwości podane są nad każdym zdaniem.","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"Na początku był to właściwie eksperyment i przychodziło bardzo niewielu uczestników.","why":"*Heimweh* (tęsknota za domem) nie ma tu sensu; nowy pomysł, który może się udać albo nie, to *Experiment*.","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"Było ich najwyżej pięciu do dziesięciu.","why":"*nur sehr wenige* → *höchstens* (najwyżej), a nie *mindestens* (co najmniej).","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"Tymczasem przychodzi jednak coraz więcej Szwajcarów, teraz na jednym spotkaniu jest często nawet ponad 30 osób.","why":"*mittlerweile* = teraz już, tymczasem (jak *inzwischen*).","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"Wszyscy pomagają za darmo i dzięki temu spotkania odbywają się bez wsparcia finansowego.","why":"*gratis* (za darmo) → pieniądze nie są potrzebne: *finanzielle Unterstützung*.","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij zdania. Podręcznik podaje kilka liter każdego słowa (widać je nad zdaniem); wpisz całe słowo.","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"Jest mi smutno, bo nie jestem w domu. Tęsknię za domem.","why":"*das Heimweh* = tęsknota za domem; *Heimweh haben*.","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"Najważniejsze przy gotowaniu indyjskich potraw są odpowiednie przyprawy.","why":"*das Gewürz, die Gewürze* = przyprawa, przyprawy; liczba mnoga ze względu na *sind*.","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"Moi dziadkowie mieli kilka sklepów. Byli ludźmi interesu, którzy odnieśli sukces.","why":"*die Geschäftsleute* = liczba mnoga od *der Geschäftsmann / die Geschäftsfrau*.","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"Nasz sąsiad o każdej porze dnia słucha głośnej muzyki. Przeszkadza to nam wszystkim, ale on nie liczy się z innymi.","why":"*Rücksicht nehmen (auf)* = liczyć się (z kimś), brać pod uwagę innych.","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"Kiedy ktoś zakłada własny biznes, często wiąże się to z ryzykiem finansowym.","why":"*das Risiko* jest rodzaju nijakiego, więc *ein finanzielles Risiko*.","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"Mój wujek ma dużo dobrych pomysłów. Rozwiązuje prawie każdy problem.","why":"*ein Problem lösen* = rozwiązać problem; *er löst*.","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"Litery i dźwięki: *b – p, g – k, d – t*. (Części a i b to zadania ze słuchania i zostały pominięte.)","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"Uzupełnij regułę: jak wymawia się *b, d, g* na końcu słowa? Spójrz na *halb, Geld, Tag*.","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"Na końcu słowa wymawia się *b, d, g* jak *p, t, k*.","why":"*halb* brzmi jak „halp”, *Geld* jak „Gelt”, *Tag* jak „Tak”. To samo dzieje się przed inną spółgłoską: *Erfolg*, *Auftrag*, *ab und zu*.","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Chcę być przy sklepie, żeby tam czekać.","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Cele Margarety. W każdym wierszu jest życzenie (po lewej) i ta sama myśl jako cel z *um … zu* (po prawej). Uzupełnij luki po tej stronie, której brakuje.","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"Chciałaby zdobyć zawód. → żeby zdobyć zawód.","why":"Życzenie: *möchte* + bezokolicznik na końcu. W *um … zu* czasownik modalny odpada.","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"Chciałaby stać się bardziej samodzielną. → żeby stać się bardziej samodzielną.","why":"*um* otwiera grupę, *zu* + bezokolicznik ją zamyka. *möchte* znika.","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"Chciałaby zarabiać pieniądze. → żeby zarabiać pieniądze.","why":"Z powrotem do życzenia: *Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"Chciałaby być blisko swojego chłopaka. → żeby być blisko swojego chłopaka.","why":"*um … zu sein*; *ihres Freundes* to dopełniacz po *in der Nähe*.","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"Po co ci ludzie to robią? Wybierz z ramki cel, który pasuje do każdego zdania, i dodaj go jako *um … zu* + bezokolicznik. *gesund bleiben* jest użyte w przykładzie.","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Peter od poniedziałku do piątku wstaje bardzo wcześnie, żeby być pierwszy w biurze.","why":"Ta sama osoba (Peter), więc *um … zu*; *sein* idzie na koniec razem z *zu*.","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"W weekend zawsze chodzę na targ, żeby kupić świeże składniki i przyprawy.","why":"Wszystko, co należy do *kaufen*, stoi przed *zu kaufen*.","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"Pan Aryan jedzie jutro do Genewy, żeby spotkać się z ważnym klientem.","why":"*um … zu treffen*; dopełnienie *einen wichtigen Kunden* stoi w środku.","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina robi kurs doszkalający zawodowo, żeby mieć większe szanse na rynku pracy.","why":"Ta sama osoba (Sabina): *um … zu haben*.","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"Dlaczego Yaroslav przyjechał do Szwajcarii?","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"Przeczytaj tekst i uzupełnij powody słowami z tekstu.","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"Jego żona może mieszkać w mieście za granicą.","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"Jego dzieci mogą chodzić do dobrej szkoły.","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"Cały zespół programistów jest w Zug.","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Chcę być przy sklepie, żeby tam czekać.","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"Przepisz powody z a jako zdania z *damit*: *Yaroslav ist in die Schweiz gekommen, damit …* Czasownik idzie na koniec.","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav przyjechał do Szwajcarii, żeby jego żona mogła mieszkać w mieście za granicą.","why":"Inna osoba (jego żona), więc tylko *damit*; *kann* idzie na sam koniec.","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav przyjechał do Szwajcarii, żeby jego dzieci mogły chodzić do dobrej szkoły.","why":"Inna osoba (jego dzieci): *damit … besuchen können*.","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav przyjechał do Szwajcarii, żeby cały zespół programistów był w Zug.","why":"Inny podmiot (zespół): *damit … ist*.","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Dlaczego Yaroslav wstaje wcześnie? Sprawdź, kto wykonuje drugą czynność. Ta sama osoba: napisz zdanie i z *damit*, i z *um … zu*. Inna osoba: pasuje tylko *damit*.","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav wstaje wcześnie, żeby móc w spokoju wypić kawę.","why":"Ta sama osoba (*er*). *will* zmienia się w *kann* w zdaniu z *damit*; czasownik idzie na koniec.","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav wstaje wcześnie, żeby w spokoju wypić kawę.","why":"Ta sama osoba, więc działa też *um … zu*: bez podmiotu, bez *will*.","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav wstaje wcześnie, żeby łazienka była potem wolna dla rodziny.","why":"Inny podmiot (*das Badezimmer*): tylko *damit*. *soll* odpada: *damit … frei ist*.","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Typowy tydzień Marcella (A), jego żony (B) i ich dzieci (C). Połącz każdą parę w jedno zdanie. Użyj *um … zu*, gdy osoba jest ta sama, w przeciwnym razie *damit*. Gdy pasują obie formy, każda jest uznawana.","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"Raz w tygodniu jeżdżę do supermarketu, żeby moja żona nie musiała robić ciężkich zakupów.","why":"Inna osoba (*meine Frau*): tylko *damit*. Tutaj *muss* zostaje, bo niesie znaczenie (*nicht machen muss* = nie musi).","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"W południe gotuję w domu, żeby dzieci miały coś ciepłego do jedzenia, kiedy wrócą ze szkoły.","why":"Inna osoba (*die Kinder*): *damit*; *sollen* odpada.","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"Poprawiam swój niemiecki na kursie językowym, żeby dobrze radzić sobie na co dzień.","why":"Ta sama osoba: pasują obie formy. *zurechtkommen* jest rozdzielnie złożony: *zurecht**zu**kommen*. *will* odpada.","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"Po szkole dużo uczymy się po południu, żeby mieć dobre oceny i dobrze ukończyć szkołę.","why":"Ta sama osoba (*wir*): pasują obie formy. Przy dwóch czasownikach każdy dostaje własne *zu*.","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"Pomagamy w domu, żeby mama nie robiła wszystkiego sama.","why":"Inna osoba (*Mama*): tylko *damit*; *soll* odpada.","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"Chcę być przy sklepie, żeby tam czekać.","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Co jest poprawne? Wpisz *um* albo *damit*. Spójrz na koniec zdania: *zu* + bezokolicznik wymaga *um*; odmieniony czasownik na końcu wymaga *damit*.","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime dużo się uczy i pracuje, żeby wkrótce założyć własną firmę.","why":"*zu machen* na końcu → *um*.","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"Said oprócz niemieckiego uczy się też angielskiego, żeby mieć większe szanse na rynku pracy.","why":"*zu haben* na końcu → *um*.","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Irina pracuje teraz na pełen etat, żeby jej mąż mógł zrobić drogi kurs doszkalający.","why":"Nowy podmiot *ihr Mann* i *kann* na końcu → *damit*.","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"Pan Pfister płaci dużo pieniędzy, żeby jego rodzicami opiekowała się prywatna opiekunka.","why":"Nowy podmiot *seine Eltern*, strona bierna *gepflegt werden* na końcu → *damit*.","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"Po co Marcello to robi?","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"Dopasuj każdą czynność Marcella (1–6) do osoby, która z niej korzysta (*Er, Seine Frau, Sein Team*), i do celu (a–f). Wpisz osobę, a potem literę.","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"Jest pierwszy w biurze. → On, e (może bez przeszkód zaplanować swój dzień pracy).","why":"Puste biuro oznacza brak przeszkód.","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"Zostawia samochód w domu. → Jego żona, d (może w ciągu dnia zrobić zakupy samochodem).","why":"Jeśli on nie weźmie samochodu, może z niego korzystać jego żona.","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"Czasem robi nadgodziny. → Jego zespół, b (może na czas skończyć wspólny projekt).","why":"Nadgodziny pomagają we wspólnym projekcie.","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"Czasem pracuje też w sobotę. → On, c (chce w dni powszednie wychodzić wcześniej).","why":"Dzięki pracy w sobotę ma krótsze dni powszednie.","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"Kładzie dzieci spać. → Jego żona, a (powinna mieć wieczorem trochę spokoju).","why":"Wieczorem ona ma spokój.","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"Napisz zdania na podstawie odpowiedzi z a. Ta sama osoba (*Er*): *um … zu* albo *damit*. Inna osoba: tylko *damit*. Usuń *will* i *soll*.","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"Jest pierwszy w biurze, żeby bez przeszkód zaplanować swój dzień pracy.","why":"Ta sama osoba: pasują obie formy.","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"Zostawia samochód w domu, żeby jego żona mogła w ciągu dnia zrobić zakupy samochodem.","why":"Inna osoba: tylko *damit*.","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"Czasem robi nadgodziny, żeby jego zespół mógł na czas skończyć wspólny projekt.","why":"Inny podmiot: tylko *damit*.","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"Czasem pracuje też w sobotę, żeby w dni powszednie wychodzić wcześniej.","why":"Ta sama osoba: pasują obie formy; *will* odpada.","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"Kładzie dzieci spać, żeby jego żona miała wieczorem trochę spokoju.","why":"Inna osoba: *damit*; *soll* odpada.","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"Praca i kariera: co jest ważne dla sukcesu w pracy? Znajdź w diagramie literowym jeszcze pięć słów i uzupełnij zdania. *Kompetenzen* to przykład. Przymiotniki wpisuj małą literą.","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"Na przykład ważne jest, żeby ktoś umiał dobrze pracować w zespole i szedł też na kompromisy. Wtedy potrafi pracować w zespole.","why":"*teamfähig* = umiejący pracować w zespole.","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"Jeśli koledzy się kłócą, ale w końcu razem znajdują dobre rozwiązanie swojego problemu, to umieją radzić sobie z konfliktami.","why":"*konfliktfähig* = umiejący radzić sobie z konfliktami.","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"Kto jest otwarty, umie dobrze rozmawiać z ludźmi, ale też dobrze słuchać, ten ma dobre umiejętności komunikacyjne.","why":"Przymiotnik przed rzeczownikiem w liczbie mnogiej po *gute*: *kommunikative Kompetenzen*.","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"W każdym razie pracownik musi wykazywać motywację i zaangażowanie, żeby odnieść sukces w pracy.","why":"*die Motivation* i *das Engagement* (zaangażowanie); kolejność dowolna.","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Robić coś, zamiast tylko marzyć","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"Niezadowolony w pracy","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"Porównaj dwa krótkie zdania z długim. Które słowo oznaczające „nie / żaden” znika w wersji z *statt … zu* albo *ohne … zu*? Wpisz je.","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"Szef ma ciągle zły humor. Nie ma ku temu żadnego powodu. / Szef ma ciągle zły humor, choć nie ma ku temu powodu. → keinen","why":"*ohne* już znaczy „nie”: po *ohne* *keinen Grund* zmienia się w *einen Grund*.","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"Które zakończenie jest poprawne? Dwie możliwości podane są nad każdym zdaniem. Wpisz poprawne zakończenie.","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"Zmieniam pracę, zamiast dalej złościć się na nią.","why":"Po *statt* nie ma *nicht*: *statt* już mówi „nie to”.","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"Szukam nowej pracy, nie informując szefa.","why":"Po *ohne* nie ma *nicht*: *ohne den Chef nicht zu informieren* znaczyłoby coś odwrotnego.","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"Praca z domu. Drugą część (to, czego nie robisz) zamień na *statt … zu* + bezokolicznik. Pomiń *nicht / keine*.","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"Ma Pan elastyczne godziny pracy, zamiast pracować od 9 do 17.","why":"*nicht* znika; *zu arbeiten* idzie na koniec.","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"Nie ma Pan kosztów dojazdu, zamiast wydawać dużo pieniędzy na benzynę.","why":"*ausgeben* jest rozdzielnie złożony: *aus**zu**geben*.","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"Sprząta Pan mieszkanie, zamiast pracować.","why":"Do *arbeiten* nic więcej nie należy, więc grupa to po prostu *statt zu arbeiten*.","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"Musi Pan sam rozwiązywać wiele problemów, zamiast omawiać je z kolegami.","why":"*sie* = problemy; zostaje w grupie.","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Moja pracowita koleżanka Olga. Połącz dwa zdania. Coś, co robi *zamiast* czegoś innego → *statt … zu*. Coś, co *w tym samym czasie* się nie dzieje → *ohne … zu*. Usuń *nicht / kein*.","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"Przychodzi do biura już o 7, zamiast zaczynać dopiero o 9.","why":"Godzina 7 zastępuje godzinę 9 → *statt*. *anfangen*: *an**zu**fangen*.","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"Zawsze jeździ do pracy na rowerze, zamiast brać samochód.","why":"Rower zastępuje samochód → *statt*. (*das Velo* = szwajcarskie słowo na rower).","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"W porze obiadowej idzie pobiegać, zamiast coś zjeść.","why":"Bieganie zastępuje obiad → *statt*.","source":"komma","check":"Oficjalny klucz podaje *statt etwas zu essen*. *ohne etwas zu essen* (biega i nic nie je) też jest poprawne po niemiecku i znaczy tu prawie to samo."},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"Pracuje wiele godzin z rzędu, nie robiąc przerwy.","why":"Podczas pracy nie ma przerwy → *ohne*. *keine Pause* zmienia się w *eine Pause*.","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"Powinna bardziej dbać o siebie, zamiast tyle pracować.","why":"Dbanie o siebie powinno zastąpić tyle pracy → *statt*.","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Robić coś, zamiast tylko marzyć","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"Poranne nawyki. Wpisz *ohne* albo *statt*. *statt* = zamiast (jedna rzecz zastępuje drugą); *ohne* = bez (coś w tym samym czasie się nie dzieje).","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"Rano zawsze biorę zimny prysznic, zamiast brać ciepłą kąpiel.","why":"Zimny prysznic zastępuje ciepłą kąpiel.","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"Nigdy nie piję kawy, nie czytając gazety.","why":"*nie … ohne* = za każdym razem, gdy piję kawę, czytam gazetę.","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"Nigdy nie wychodzę z domu bez parasola.","why":"*nie … ohne* = zawsze go biorę.","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"Rano po przebudzeniu zawsze leżę jeszcze pół godziny, zamiast od razu wstać.","why":"Leżenie w łóżku zastępuje wstawanie.","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"Co chciałbyś robić w życiu? Połącz życzenie z lewej części ramki z czymś z prawej części, używając *ohne … zu* albo *statt … zu*. Przekreślone słowa są użyte w przykładzie. Przykładowa odpowiedź to jedna z możliwości.","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"Chętnie zarabiałbym więcej pieniędzy, zamiast musieć oszczędzać każdego franka. Chętnie naprawiałbym zepsute rzeczy, zamiast wyrzucać je do śmieci. Chętnie dzwoniłbym do rodziny w ojczyźnie, nie tęskniąc za domem. Chętnie jeździłbym na rowerze, zamiast zawsze chodzić pieszo. Chętnie mówiłbym dobrze po niemiecku, nie chodząc na wiele kursów językowych. Chętnie mieszkałbym razem z rodziną, zamiast żyć sam.","why":"Życzenie z *würde gern* / *wäre gern*, potem *statt … zu* (zastąpienie) albo *ohne … zu* (coś się nie dzieje). Z czasownikiem modalnym: *sparen **zu müssen***.","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"Niezadowolona w nowej pracy: rady dla przyjaciółki","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Uzupełnij rady zwrotami z ramki. Każdy jest użyty raz; *Wie wäre es, wenn* jest użyte w przykładzie.","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"Jeśli chcesz lepiej poznać kolegów z pracy, może powinnaś częściej w ciągu dnia zaglądać na chwilę do firmowej kuchni. Tam możesz spokojnie porozmawiać ze wszystkimi, nie przeszkadzając im w pracy.","why":"Po zdaniu z *wenn* czasownik stoi na początku: *…, solltest du vielleicht …*; *gehen* idzie na koniec.","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"Co sądzisz o pomyśle, żeby któregoś dnia przynieść ciasto dla kolegów z twojego działu i uczcić swój pierwszy miesiąc w nowej firmie? Z ciasta wszyscy się cieszą.","why":"*Wie findest du die Idee, … zu …?* to pytanie z *zu* + bezokolicznik.","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"Na twoim miejscu chodziłabym wszędzie tam, gdzie można spotkać kolegów z pracy. Mogłabyś na przykład wziąć udział w firmowym programie sportowym. Tam poznasz też ludzi z innych działów.","why":"*An deiner Stelle würde ich …* (na twoim miejscu); *Du könntest zum Beispiel …* + bezokolicznik na końcu.","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"Mogę ci tylko radzić, żebyś była otwarta i myślała pozytywnie. Zobaczysz, za kilka tygodni będzie ci już lepiej.","why":"*Ich kann dir nur raten, … zu …*: rada występuje jako *zu* + bezokolicznik.","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"Napisz jeszcze dwie rady dla przyjaciółki. Przykładowa odpowiedź to jedna z możliwości.","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"Mogę ci tylko radzić, żebyś porozmawiała ze swoją szefową. Co sądzisz o pomyśle, żeby umówić się po pracy z kolegami?","why":"Oba zwroty mają na końcu *zu* + bezokolicznik; przy czasowniku zwrotnym zaimek zostaje w środku: *dich … zu verabreden*.","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"Rozmowy w sklepie","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"Poproszę …","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"Kto co mówi? Wpisz *K* dla klientki (*Kundin*) albo *V* dla sprzedawczyni (*Verkäuferin*).","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"Czy mogę Pani polecić …? → sprzedawczyni","why":"Polecanie to zadanie sprzedawczyni.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"Muszę się jeszcze nad tym zastanowić. → klientka","why":"Klientka jeszcze się nie zdecydowała.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"Potrzebuje Pani pomocy? → sprzedawczyni","why":"Propozycja pomocy.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"Czym mogę służyć? → sprzedawczyni","why":"Sprzedawczyni pyta, czego sobie życzysz.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"Przepraszam, czy można …? → klientka","why":"Klientka o coś prosi.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"Czy życzy sobie Pani czegoś jeszcze? → sprzedawczyni","why":"Pytanie pod koniec zakupów.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"Szukam … → klientka","why":"Klientka mówi, czego potrzebuje.","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"Poproszę … → klientka","why":"Uprzejmy sposób proszenia o coś (Konjunktiv II).","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"W czym mogę Pani pomóc? → sprzedawczyni","why":"Propozycja pomocy.","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"Szuka Pani czegoś konkretnego? → sprzedawczyni","why":"Sprzedawczyni pyta, czego sobie życzysz.","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"Czy mogę Pani zaproponować …? → sprzedawczyni","why":"Proponowanie czegoś.","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"Nie mogę się jeszcze zdecydować. → klientka","why":"Klientka się nie zdecydowała.","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"Czy mogłabym o coś Panią zapytać? Czy można …? → klientka","why":"Uprzejme pytanie (Konjunktiv II *dürfte*).","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"Czy chciałaby Pani coś jeszcze? → sprzedawczyni","why":"Pytanie pod koniec zakupów.","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"Które zdanie po prawej (a–h) znaczy to samo co każde zdanie po lewej? Wpisz literę.","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"Czy mogę Pani polecić …? → e Czy mogę Pani zaproponować …?","why":"Oba zdania coś proponują klientce.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"Muszę się jeszcze nad tym zastanowić. → f Nie mogę się jeszcze zdecydować.","why":"Oba mówią: jeszcze nie zdecydowałam.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"Potrzebuje Pani pomocy? → b W czym mogę Pani pomóc?","why":"Oba proponują pomoc.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"Czym mogę służyć? → d Szuka Pani czegoś konkretnego?","why":"Oba pytają, czego chce klientka.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"Przepraszam, czy można …? → g Czy mogłabym o coś Panią zapytać? Czy można …?","why":"Oba to uprzejme pytania klientki.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"Czy życzy sobie Pani czegoś jeszcze? → h Czy chciałaby Pani coś jeszcze?","why":"Oba pytają, czy klientka chce czegoś więcej.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"Szukam … → a Poproszę …","why":"Oba mówią, czego chce klientka.","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"Reklamacje","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij zdania z listów z reklamacją. Podręcznik podaje kilka liter każdego słowa (widać je nad zdaniem); wpisz całe słowo. (Ćwiczenie 22 to zadanie ze słuchania i zostało pominięte).","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"Wzywam Państwa po raz ostatni do udzielenia mi odpowiedzi do 31.03.","why":"*jemanden auffordern, … zu …* = wezwać kogoś do czegoś, zażądać od kogoś, żeby …; czasownik rozdzielnie złożony: *ich fordere … auf*.","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"Niestety zegarek, który kupiłem wczoraj, nie działa. Proszę przysłać mi produkt zastępczy. Mam prawo do nowego zegarka.","why":"*der Ersatz* = produkt zastępczy; *Anspruch haben auf* + biernik = mieć prawo do.","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"Kiedy otworzyłem paczkę, niestety stwierdziłem, że … jest uszkodzony/uszkodzona.","why":"*beschädigt* = uszkodzony.","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"Pisałem do Państwa już dwa razy i nie otrzymałem odpowiedzi. To naprawdę bardzo irytujące.","why":"*ärgerlich* = irytujący.","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"Sweter jest ładny, ale niestety nie pasuje na mojego męża. Dlatego chciałabym go wymienić na rozmiar większy.","why":"*umtauschen* = wymienić (w sklepie).","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"Niestety nadal nie otrzymałem odpowiedzi.","why":"*die Antwort* = odpowiedź.","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"Proszę potwierdzić mi na piśmie, że otrzymali Państwo moją reklamację.","why":"*bestätigen* = potwierdzić.","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"Jestem bardzo zdenerwowany i bardzo rozczarowany Państwa obsługą.","why":"*verärgert* = zdenerwowany; *enttäuscht von* = rozczarowany (czymś).","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"Reklamacja na piśmie","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"Zdania po lewej pokazują, jak pisze się w liście z reklamacją; ramka pokazuje, jak powiedziałbyś to na co dzień. Wpisz literę (a–g) o tym samym znaczeniu.","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"16.2. dostarczyli mi Państwo … → g","why":"Oba mówią, co otrzymałeś i kiedy.","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"Napisałem do Państwa już dwa e-maile z prośbą o przesłanie mi produktu zastępczego. → b","why":"*bereits* = *schon*; *Ersatz* = nowy egzemplarz. (*das E-Mail* to użycie szwajcarskie).","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"Niestety nadal nie otrzymałem odpowiedzi. → f","why":"Wciąż brak odpowiedzi → rozczarowanie.","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"Muszę powiedzieć, że bardzo zawiodłem się na Państwa obsłudze. → e","why":"Oczekiwałeś lepszej obsługi.","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"Wzywam Państwa po raz ostatni do przesłania mi produktu zastępczego do … → d","why":"*zum letzten Mal* = *ein letztes Mal*.","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"Jeśli do … nie otrzymam od Państwa odpowiedzi, zrezygnuję z zamówienia. → a","why":"*auf etwas verzichten* = obejść się bez czegoś, zrezygnować z czegoś.","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"Wybierz sytuację i napisz reklamację tak jak w a. Pomogą ci zdania 1–7. Przykładowe odpowiedzi to za każdym razem jedna z możliwości.","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"Szanowni Państwo / 12.3. dostarczyli mi Państwo słuchawki. Niestety nie działają. Pisałem już do Państwa raz, ale nie otrzymałem odpowiedzi. Wzywam Państwa po raz ostatni do przesłania mi produktu zastępczego do 12.4. Jeśli znowu nie otrzymam od Państwa odpowiedzi, zrezygnuję z zamówienia. / Z poważaniem / Luca Carelli","why":"Najważniejsze punkty po kolei: co otrzymałeś i kiedy, co jest nie tak, co zrobiłeś, co firma musi zrobić (*auffordern, … zu …*), co zrobisz w przeciwnym razie.","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"Szanowni Państwo / 3.5. dostarczyli mi Państwo torbę na laptopa. Niestety już po tygodniu urwał się pasek na ramię. To bardzo irytujące. Odsyłam Państwu dziś torbę i proszę o jej wymianę albo przesłanie mi produktu zastępczego. W załączniku znajdą Państwo kopię rachunku. Proszę potwierdzić mi na piśmie, że otrzymali Państwo moją reklamację. / Z poważaniem / Maria Keller","why":"Nasz własny wzór (klucz nie podaje wzoru dla sytuacji 2). *bitten, … zu …*: *umzutauschen* (czasownik rozdzielnie złożony).","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"Test do Lektion 6","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Uzupełnij tekst. Podręcznik podaje kilka liter każdego słowa (widać je nad zdaniem); wpisz całe słowo.","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"… ale w pewnym momencie byłem niezadowolony i podjąłem decyzję: zaczynam działać na własny rachunek jako handlowiec i zakładam firmę.","why":"*sich entschliessen* (Perfekt: *hat sich entschlossen*) = zdecydować się. *der Kaufmann* = handlowiec, kupiec.","source":"g6865","check":"Podane litery wskazują na *Kaufmann*; kobieta napisałaby *Kauffrau*, które ma inny układ liter. Obie formy są uznawane. Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"Pomaga mi w tym kilku przyjaciół, którzy są dobrymi ludźmi interesu.","why":"*die Geschäftsleute* = ludzie interesu (liczba mnoga).","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"Nie sądzę, żeby to było ryzyko finansowe. Wręcz przeciwnie, myślę, że to się opłaca.","why":"*ein finanzielles Risiko* (rodzaj nijaki); *es lohnt sich* = to się opłaca, warto.","source":"platzhalter","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"Połącz dwa zdania. Użyj *um … zu*, gdy osoba jest ta sama; w przeciwnym razie użyj *damit*.","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás robi kurs doszkalający, żeby poprawić swoje umiejętności komunikacyjne.","why":"Ta sama osoba (Tomás) → *um … zu*; *möchte* odpada.","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"Pani Seil pracuje tylko na pół etatu, żeby dzieci nie były same, kiedy wracają ze szkoły.","why":"Inna osoba (dzieci) → *damit*; *sollen* odpada.","source":"damit","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Rodolfo opiekuje się w tym tygodniu dziećmi, żeby jego żona mogła odwiedzić swoją chorą matkę.","why":"Inna osoba (jego żona) → *damit*; *kann* idzie na koniec.","source":"damit","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"Wpisz *ohne* albo *statt* w pierwszą lukę i *zu* w drugą.","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"Ktoś umie iść na kompromis, jeśli w sporze dogaduje się z drugą osobą, zamiast kłócić się bez rezultatu.","why":"Porozumienie zastępuje kłótnię → *statt*.","source":"komma","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"Dobry szef to ktoś, kto kieruje swoimi pracownikami, nie traktując siebie zbyt poważnie.","why":"Kieruje i jednocześnie nie traktuje siebie zbyt poważnie → *ohne*. Pierwsze *zu* znaczy „zbyt”.","source":"komma","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"Kto potrafi pracować w zespole, chętnie współpracuje z kolegami, zamiast zawsze robić wszystko sam.","why":"Praca zespołowa zastępuje pracę w pojedynkę → *statt*.","source":"komma","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"Elastyczny jest ktoś, kto potrafi szybko i bez problemów przyzwyczaić się do nowych sytuacji, nie stresując się.","why":"Stresu nie ma → *ohne*.","source":"komma","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"Przed rozmową kwalifikacyjną: rady dla przyjaciela. Wpisz zwrot, który pasuje do reszty zdania. Dwie możliwości podane są nad każdym zdaniem.","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"A może przemyślałbyś kilka pytań, które możesz jutro zadać?","why":"*du … überlegst* z czasownikiem na końcu wymaga *wenn*: *Wie wäre es, wenn …?*","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"Mógłbyś na przykład zapytać, jak duży jest zespół albo jakie będą twoje zadania.","why":"Po czasowniku modalnym stoi czysty bezokolicznik (*fragen*): *Du könntest … fragen*.","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"Mogę ci tylko radzić, żebyś był sobą. To jest najważniejsze ze wszystkiego.","why":"*zu sein* wymaga zwrotu, po którym stoi *zu* + bezokolicznik: *Ich kann dir nur raten, …*","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"Co powiesz na to, żeby pójść dziś wieczorem coś zjeść na mieście? To pozwoli ci zająć myśli czymś innym.","why":"*essen zu gehen* (zu + bezokolicznik) pasuje do *Was hältst du davon, … zu …?*","source":"g6865","check":"Klucz odpowiedzi do Arbeitsbuch nie obejmuje testu do lekcji; ta odpowiedź jest nasza, sprawdzona w grammis."}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"W pracy: życzenia klientów","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"Pracujcie w trójkach: każdy bierze jedną rolę i odgrywacie trzy rozmowy telefoniczne. Ćwicz, pisząc je albo mówiąc; dialogi wzorcowe to jedna z możliwości. (Ćwiczenia 1 i 2 to zadania ze słuchania i zostały pominięte).","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"Klientka: Dzień dobry, mówi Meier. Zamówiłam u Państwa trzy skrzynki wody mineralnej i cztery skrzynki soku jabłkowego. Właśnie przyszła dostawa, ale to siedem skrzynek wody mineralnej. Zamówiłam sok jabłkowy, a nie tylko wodę! / Pracownik: Och, przykro mi. Chyba zaszedł jakiś błąd. Zaraz zadzwonię do kolegi. Proszę podać mi numer komórki, zaraz do Pani oddzwonię.","why":"Reklamacja: powiedz, co zamówiłeś i co przyszło (*bestellt … und nicht …*). Pracownik przeprasza i obiecuje oddzwonić. (*der Harass* = szwajcarskie słowo na skrzynkę; *der Süssmost* = szwajcarski sok jabłkowy).","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"Pracownik: Cześć, Marco, dzwoniła pani Meier. Dostarczyłeś jej siedem skrzynek wody mineralnej zamiast trzech skrzynek wody i czterech skrzynek soku jabłkowego. / Kierowca: O rany, chyba coś pomyliłem. Co teraz zrobimy? Mógłbym dziś po południu pojechać tam jeszcze raz. / Pracownik: Dobrze, zrobimy tak: zawieziesz jej cztery skrzynki soku jabłkowego i odbierzesz z powrotem cztery skrzynki wody. Zadzwonię i zapytam, czy to jest w porządku.","why":"Koledzy z pracy mówią sobie *du*. Tutaj *statt* + rzeczownik (*statt drei Harasse Wasser*): ta sama myśl co w *statt … zu*, ale z rzeczą.","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"Pracownik: Pani Meier, strasznie mi przykro. Mój kolega popełnił błąd. Moglibyśmy przywieźć Pani sok jabłkowy jeszcze dziś do 17:00. Oczywiście udzielimy Pani rabatu w wysokości 20 procent. / Klientka: Tak, zgadzam się na to. Przyjęcie zaczyna się dopiero o 18:00. Dziękuję bardzo!","why":"Zaproponuj rozwiązanie za pomocą *Wir könnten Ihnen …* (Konjunktiv II = uprzejmie). Klientka się zgadza: *damit bin ich einverstanden* (tutaj *damit* = z tym, a nie *żeby*).","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (oficjalny klucz odpowiedzi, Lektion 6)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um … zu nie ma własnego podmiotu; pochodzi on ze zdania głównego)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis, słownik spójników: damit (spójnik podrzędny z czasownikiem na końcu; także przysłówek znaczący „z tym”)","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (zdania bezokolicznikowe z um, ohne, (an)statt oddziela się przecinkiem)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis: Platzhalter (es na pierwszym miejscu; formalne es przy czasownikach pogodowych zostaje: Heute schneit es)","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis: Korrelat (es zapowiadające zdanie: Ich kann es nicht erwarten, euch zu sehen)","url":"https://grammis.ids-mannheim.de/vggf/2283"}]}];
